                    <span style={{ flex: '1.3 1 0', fontSize: 12.5, color: '#52555c', fontWeight: 600 }}>{r[0]}</span>
                    {vals
                      ? vals.map((v, vi) => <span key={vi} style={{ flex: '1 1 0', textAlign: 'center', fontSize: 12.5, color: '#16181d', fontWeight: 700, fontFamily: 'var(--mono)', direction: 'ltr' }}>{v}</span>)
                      : <span style={{ flex: '3 1 0', textAlign: 'center', fontSize: 12.5, color: '#16181d', fontWeight: 700, fontFamily: 'var(--mono)', direction: 'ltr' }}>{r[1]}</span>}
