/* ============ New Catalog wizard ============ */
function ScreenNewCatalog({ go }) {
  const { BRANDS, TEMPLATES, ASSET_GROUPS } = window.DB;
  const [step, setStep] = React.useState(0);
  const [brand, setBrand] = React.useState('peugeot');
  const [tmpl, setTmpl] = React.useState('t-peu-pass');
  const [model, setModel] = React.useState('3008');
  const [trims, setTrims] = React.useState(['Pure', 'Plus', 'Performance']);
  const [gen, setGen] = React.useState(0); // generation progress phase

  const steps = ['מותג', 'תבנית', 'פרטי הדגם', 'העלאת חומרים', 'יצירה'];
  const brandTemplates = TEMPLATES.filter(t => t.brand === brand);

  // The created spec is a REAL editable document: map the chosen brand + model to a
  // scanned spec so "open in editor" loads actual pages, not the demo template.
  const imports = window.IMPORTS || [];
  const source = React.useMemo(() => {
    const m = (model || '').toLowerCase().trim();
    const byModel = m && imports.find(it => it.model.toLowerCase().replace(/^.*?\s/, '').includes(m) || it.model.toLowerCase().includes(m));
    const byBrand = imports.find(it => it.brand === brand);
    return (byModel || byBrand || imports[0] || {}).key;
  }, [brand, model]);
  const sourceModel = (imports.find(it => it.key === source) || {}).model;

  React.useEffect(() => {
    if (step === 4 && gen < 5) {
      const t = setTimeout(() => setGen(g => g + 1), gen === 0 ? 400 : 800);
      return () => clearTimeout(t);
    }
  }, [step, gen]);

  const next = () => setStep(s => Math.min(s + 1, 4));
  const back = () => setStep(s => Math.max(s - 1, 0));

  return (
    <div className="scroll">
      <div className="page-wrap" style={{ maxWidth: 1000 }}>
        {/* stepper */}
        <div style={{ display: 'flex', alignItems: 'center', gap: 0, marginBottom: 30 }}>
          {steps.map((s, i) => (
            <React.Fragment key={s}>
              <div style={{ display: 'flex', alignItems: 'center', gap: 9, opacity: i <= step ? 1 : .45 }}>
                <div style={{
                  width: 30, height: 30, borderRadius: 99, display: 'grid', placeItems: 'center', flexShrink: 0,
                  background: i < step ? 'var(--eco)' : i === step ? 'var(--accent)' : 'var(--surface-3)',
                  color: i <= step ? '#fff' : 'var(--ink-3)', fontWeight: 700, fontSize: 13,
                  boxShadow: i === step ? '0 3px 9px oklch(0.56 0.16 256 / .35)' : 'none', transition: '.2s',
                }}>{i < step ? <Icon name="check" size={16} strokeWidth={2.5} /> : i + 1}</div>
                <span style={{ fontWeight: 700, fontSize: 13.5, color: i === step ? 'var(--ink)' : 'var(--ink-3)', whiteSpace: 'nowrap' }}>{s}</span>
              </div>
              {i < steps.length - 1 && <div style={{ flex: 1, height: 2, background: i < step ? 'var(--eco)' : 'var(--line)', margin: '0 12px', transition: '.3s' }} />}
            </React.Fragment>
          ))}
        </div>

        <div key={step} className="fade-up">
          {step === 0 && <StepBrand brands={BRANDS} value={brand} onChange={setBrand} />}
          {step === 1 && <StepTemplate templates={brandTemplates} value={tmpl} onChange={setTmpl} />}
          {step === 2 && <StepModel model={model} setModel={setModel} trims={trims} setTrims={setTrims} brand={BRANDS.find(b => b.id === brand)} />}
          {step === 3 && <StepUpload groups={ASSET_GROUPS} />}
          {step === 4 && <StepGenerate gen={gen} go={go} model={model} source={source} sourceModel={sourceModel} />}
        </div>

        {/* footer nav */}
        {step < 4 && (
          <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: 30, paddingTop: 20, borderTop: '1px solid var(--line)' }}>
            <button className="btn btn-subtle" onClick={step === 0 ? () => go('dashboard') : back}>
              <Icon name="chevR" size={16} /> {step === 0 ? 'ביטול' : 'הקודם'}
            </button>
            <button className="btn btn-primary btn-lg" onClick={next}>
              {step === 3 ? <><Icon name="sparkle" /> צור מפרט</> : <>המשך <Icon name="chevL" size={16} /></>}
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

function StepHead({ title, sub }) {
  return <div style={{ marginBottom: 22 }}>
    <h2 style={{ fontSize: 24, fontWeight: 800, letterSpacing: '-.5px', fontFamily: 'var(--display)' }}>{title}</h2>
    <p style={{ color: 'var(--ink-2)', fontSize: 14.5, marginTop: 4 }}>{sub}</p>
  </div>;
}

function StepBrand({ brands, value, onChange }) {
  return <div>
    <StepHead title="בחר מותג" sub="לכל מותג שפת עיצוב ותבניות משלו." />
    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2,1fr)', gap: 14 }}>
      {brands.map(b => (
        <button key={b.id} onClick={() => onChange(b.id)} className="card pick-card"
          style={{ display: 'flex', alignItems: 'center', gap: 15, padding: 18, textAlign: 'start',
            borderColor: value === b.id ? 'var(--accent)' : 'var(--line)',
            boxShadow: value === b.id ? '0 0 0 3px oklch(0.56 0.16 256 / .12)' : 'var(--sh-sm)' }}>
          <BrandBadge brand={b} size={48} />
          <div style={{ flex: 1 }}>
            <div style={{ fontWeight: 800, fontSize: 16 }}>{b.name}</div>
            <div style={{ color: 'var(--ink-3)', fontSize: 13 }}>{b.kind}</div>
          </div>
          <CheckRing on={value === b.id} />
        </button>
      ))}
    </div>
  </div>;
}

function StepTemplate({ templates, value, onChange }) {
  return <div>
    <StepHead title="בחר תבנית" sub="המבנה, הטיפוגרפיה והצבעוניות ייקבעו לפי התבנית." />
    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3,1fr)', gap: 16 }}>
      {templates.map((t, i) => (
        <button key={t.id} onClick={() => onChange(t.id)} className="card pick-card" style={{ overflow: 'hidden', textAlign: 'start', padding: 0,
          borderColor: value === t.id ? 'var(--accent)' : 'var(--line)',
          boxShadow: value === t.id ? '0 0 0 3px oklch(0.56 0.16 256 / .12)' : 'var(--sh-sm)' }}>
          <TemplateThumb accent={t.accent} kind={i} />
          <div style={{ padding: 14 }}>
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
              <span style={{ fontWeight: 800, fontSize: 14 }}>{t.name}</span>
              <CheckRing on={value === t.id} />
            </div>
            <div style={{ color: 'var(--ink-3)', fontSize: 12.5, marginTop: 4 }}>{t.pages} עמ׳ · {t.size}</div>
          </div>
        </button>
      ))}
    </div>
  </div>;
}

function StepModel({ model, setModel, trims, setTrims, brand }) {
  const allTrims = ['Pure', 'Plus', 'Performance', 'GT', 'Sport'];
  const toggle = (t) => setTrims(p => p.includes(t) ? p.filter(x => x !== t) : [...p, t]);
  return <div>
    <StepHead title="פרטי הדגם" sub="שם הדגם וגרסאות הגימור שיופיעו במפרט." />
    <div className="card" style={{ padding: 24, maxWidth: 640 }}>
      <Field label="מותג">
        <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '10px 14px', background: 'var(--surface-3)', borderRadius: 10 }}>
          <BrandBadge brand={brand} size={28} /> <span style={{ fontWeight: 700 }}>{brand.name}</span>
        </div>
      </Field>
      <Field label="שם הדגם">
        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
          <span style={{ fontWeight: 800, color: 'var(--ink-3)', fontSize: 16 }}>{brand.name}</span>
          <input value={model} onChange={e => setModel(e.target.value)} className="txt-input" style={{ flex: 1 }} placeholder="3008" />
        </div>
      </Field>
      <Field label="גרסאות גימור" hint="ניתן לבחור כמה">
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
          {allTrims.map(t => (
            <button key={t} onClick={() => toggle(t)} style={{
              padding: '8px 16px', borderRadius: 10, fontWeight: 700, fontSize: 13.5, transition: '.14s',
              border: trims.includes(t) ? '1.5px solid var(--accent)' : '1.5px solid var(--line-2)',
              background: trims.includes(t) ? 'var(--accent-soft)' : 'var(--surface)',
              color: trims.includes(t) ? 'var(--accent-ink)' : 'var(--ink-2)',
              display: 'flex', alignItems: 'center', gap: 6,
            }}>{trims.includes(t) && <Icon name="check" size={14} strokeWidth={2.6} />}{t}</button>
          ))}
        </div>
      </Field>
      <Field label="שנת דגם">
        <input defaultValue="2026" className="txt-input" style={{ width: 120 }} />
      </Field>
    </div>
  </div>;
}

function Field({ label, hint, children }) {
  return <div style={{ marginBottom: 20 }}>
    <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 7 }}>
      <label style={{ fontWeight: 700, fontSize: 13.5 }}>{label}</label>
      {hint && <span style={{ fontSize: 12, color: 'var(--ink-3)' }}>· {hint}</span>}
    </div>
    {children}
  </div>;
}

function StepUpload({ groups }) {
  const [uploaded, setUploaded] = React.useState({});
  const sections = [
    { key: 'images', label: 'תמונות', icon: 'image', items: groups },
    { key: 'fonts', label: 'פונטים', icon: 'font' },
    { key: 'texts', label: 'טקסטים שיווקיים', icon: 'text' },
    { key: 'tables', label: 'טבלאות טכניות', icon: 'table' },
  ];
  return <div>
    <StepHead title="העלאת חומרים" sub="גרור קבצים לכל קטגוריה. המערכת תמקם אותם בעמודים הנכונים לפי התבנית." />
    {/* image groups */}
    <div style={{ marginBottom: 22 }}>
      <SubLabel icon="image" text="תמונות לפי קטגוריה" />
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill,minmax(150px,1fr))', gap: 12 }}>
        {groups.map(g => (
          <DropZone key={g.key} icon={g.icon} label={g.label} count={uploaded[g.key] != null ? uploaded[g.key] : g.count}
            onDrop={() => setUploaded(u => ({ ...u, [g.key]: (u[g.key] != null ? u[g.key] : g.count) + 3 }))} />
        ))}
      </div>
    </div>
    {/* other materials */}
    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3,1fr)', gap: 14 }}>
      <MaterialCard icon="font" title="פונטים" desc="קובצי OTF / TTF" items={['Peugeot New.otf', 'Heebo.ttf']} />
      <MaterialCard icon="text" title="טקסטים שיווקיים" desc="כותרות, פסקאות, RTL" items={['headlines.docx', 'descriptions.txt']} />
      <MaterialCard icon="table" title="טבלאות טכניות" desc="CSV / Excel / הזנה ידנית" items={['specs.xlsx', 'pollution.csv']} />
      <MaterialCard icon="palette" title="צבעים" desc="שמות, קודים, דוגמאות" items={['6 צבעים זוהו']} done />
      <MaterialCard icon="wheel" title="חישוקים" desc="תמונות וגדלים" items={['3 חישוקים']} done />
      <MaterialCard icon="shield" title="בטיחות וזיהום" desc="טבלאות נתונים" items={['7 מערכות', 'דרגה 1']} done />
    </div>
  </div>;
}

function SubLabel({ icon, text }) {
  return <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 11, fontWeight: 800, fontSize: 14 }}>
    <Icon name={icon} size={17} style={{ color: 'var(--accent)' }} /> {text}
  </div>;
}

function DropZone({ icon, label, count, onDrop }) {
  const [over, setOver] = React.useState(false);
  return (
    <div onClick={onDrop} onDragOver={e => { e.preventDefault(); setOver(true); }} onDragLeave={() => setOver(false)}
      onDrop={e => { e.preventDefault(); setOver(false); onDrop(); }}
      style={{ borderRadius: 12, border: `1.5px dashed ${over ? 'var(--accent)' : 'var(--line-2)'}`, background: over ? 'var(--accent-soft)' : 'var(--surface)', padding: '16px 12px', cursor: 'pointer', textAlign: 'center', transition: '.14s' }}>
      <div style={{ width: 38, height: 38, borderRadius: 10, background: 'var(--surface-3)', display: 'grid', placeItems: 'center', margin: '0 auto 9px', color: 'var(--ink-2)' }}>
        <Icon name={icon} size={19} />
      </div>
      <div style={{ fontWeight: 700, fontSize: 13 }}>{label}</div>
      <div style={{ fontSize: 11.5, color: count ? 'var(--eco)' : 'var(--ink-3)', fontWeight: 700, marginTop: 3 }}>
        {count ? `${count} קבצים` : 'גרור לכאן'}
      </div>
    </div>
  );
}

function MaterialCard({ icon, title, desc, items, done }) {
  return <div className="card" style={{ padding: 16 }}>
    <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 11 }}>
      <div style={{ width: 36, height: 36, borderRadius: 10, background: done ? 'var(--eco-soft)' : 'var(--accent-soft)', display: 'grid', placeItems: 'center', color: done ? 'var(--eco)' : 'var(--accent)' }}>
        <Icon name={icon} size={18} />
      </div>
      <div style={{ flex: 1 }}>
        <div style={{ fontWeight: 800, fontSize: 14 }}>{title}</div>
        <div style={{ fontSize: 11.5, color: 'var(--ink-3)' }}>{desc}</div>
      </div>
      {done && <Icon name="checkCircle" size={20} style={{ color: 'var(--eco)' }} />}
    </div>
    <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
      {items.map(f => (
        <div key={f} style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '7px 10px', background: 'var(--surface-3)', borderRadius: 8, fontSize: 12.5, fontWeight: 600 }}>
          <Icon name="file" size={14} style={{ color: 'var(--ink-3)' }} /> {f}
        </div>
      ))}
    </div>
  </div>;
}

function CheckRing({ on }) {
  return <div style={{ width: 22, height: 22, borderRadius: 99, flexShrink: 0, border: on ? 'none' : '2px solid var(--line-2)', background: on ? 'var(--accent)' : 'transparent', display: 'grid', placeItems: 'center', color: '#fff', transition: '.14s' }}>
    {on && <Icon name="check" size={14} strokeWidth={3} />}
  </div>;
}

function StepGenerate({ gen, go, model, source, sourceModel }) {
  const phases = [
    'מנתח את התבנית ומבנה העמודים',
    'ממקם תמונות באזורים המתאימים',
    'משבץ טקסטים שיווקיים (RTL)',
    'בונה טבלאות טכניות, צבעים וחישוקים',
    'מטמיע נתוני בטיחות וזיהום אוויר',
  ];
  const done = gen >= 5;
  return (
    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', textAlign: 'center', padding: '20px 0 10px' }}>
      <div style={{ position: 'relative', width: 120, height: 120, marginBottom: 24 }}>
        <div style={{ position: 'absolute', inset: 0, borderRadius: 30, background: done ? 'var(--eco-soft)' : 'var(--accent-soft)', display: 'grid', placeItems: 'center', transition: '.4s' }}>
          {done ? <Icon name="check" size={56} strokeWidth={2.4} style={{ color: 'var(--eco)' }} />
                : <Icon name="sparkle" size={50} style={{ color: 'var(--accent)', animation: 'pop 1s ease-in-out infinite alternate' }} />}
        </div>
        {!done && <div style={{ position: 'absolute', inset: -6, borderRadius: 34, border: '3px solid transparent', borderTopColor: 'var(--accent)', animation: 'spin 1s linear infinite' }} />}
      </div>
      <h2 style={{ fontSize: 24, fontWeight: 800, fontFamily: 'var(--display)' }}>{done ? 'המפרט מוכן!' : 'יוצר מפרט…'}</h2>
      <p style={{ color: 'var(--ink-2)', fontSize: 14.5, marginTop: 5 }}>{done ? `${sourceModel || model} · נוצר מפרט עריך לפי התבנית` : 'המערכת בונה את העמודים לפי התבנית שבחרת'}</p>

      <div className="card" style={{ width: 460, padding: 18, marginTop: 26, textAlign: 'start' }}>
        {phases.map((p, i) => {
          const state = gen > i + 1 ? 'done' : gen === i + 1 || (gen > i && gen <= i + 1) ? 'active' : gen > i ? 'done' : 'wait';
          const isDone = gen > i + 1 || done;
          const isActive = gen === i + 1 && !done;
          return (
            <div key={i} style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '9px 0', opacity: gen > i ? 1 : .4 }}>
              <div style={{ width: 22, height: 22, borderRadius: 99, display: 'grid', placeItems: 'center', flexShrink: 0,
                background: isDone ? 'var(--eco)' : isActive ? 'var(--accent-soft)' : 'var(--surface-3)' }}>
                {isDone ? <Icon name="check" size={13} strokeWidth={3} style={{ color: '#fff' }} />
                  : isActive ? <span className="spinner" style={{ width: 13, height: 13, borderColor: 'var(--accent-line)', borderTopColor: 'var(--accent)' }} />
                  : <span style={{ width: 6, height: 6, borderRadius: 99, background: 'var(--ink-3)' }} />}
              </div>
              <span style={{ fontSize: 13.5, fontWeight: isActive ? 700 : 600, color: gen > i ? 'var(--ink)' : 'var(--ink-3)' }}>{p}</span>
            </div>
          );
        })}
      </div>

      {done && (
        <div className="fade-up" style={{ display: 'flex', gap: 12, marginTop: 26 }}>
          <button className="btn btn-ghost btn-lg" onClick={() => go('dashboard')}>חזרה לדאשבורד</button>
          <button className="btn btn-primary btn-lg" onClick={() => go('editor', source ? { source } : undefined)}><Icon name="edit" /> פתח בעורך</button>
        </div>
      )}
    </div>
  );
}

