/* a slot is risky (needs manual review) when low confidence or missing a data source */
function slotRisk(s) {
  const reasons = [];
  if (s.conf < 78) reasons.push('ביטחון זיהוי נמוך');
  if (!s.source || s.source === 'ידני') reasons.push('מקור נתונים לא הוגדר');
  if (!s.name || !s.name.trim()) reasons.push('שם Slot חסר');
  return reasons;
}

