/* ============ Template Learning — Review & annotate editor ============ */

function confColor(c) { return c >= 85 ? 'var(--eco)' : c >= 78 ? 'var(--warn)' : 'var(--danger)'; }

/* ---- a single draggable + resizable detection box on the page ---- */
function SlotBox({ slot, selected, onSelect, onChange, canvasRef }) {
  const ty = SLOT_TYPES[slot.type];
  const risk = slotRisk(slot).length > 0;

  const begin = (e, mode) => {
    e.preventDefault(); e.stopPropagation();
    onSelect();
    const rect = canvasRef.current.getBoundingClientRect();
    const s = { mx: e.clientX, my: e.clientY, x: slot.x, y: slot.y, w: slot.w, h: slot.h };
    const move = (ev) => {
      const dx = (ev.clientX - s.mx) / rect.width * 100;
      const dy = (ev.clientY - s.my) / rect.height * 100;
      let n = { x: s.x, y: s.y, w: s.w, h: s.h };
      if (mode === 'move') {
        n.x = clamp(s.x + dx, 0, 100 - s.w);
        n.y = clamp(s.y + dy, 0, 100 - s.h);
      } else {
        if (mode.includes('e')) n.w = clamp(s.w + dx, 5, 100 - s.x);
        if (mode.includes('s')) n.h = clamp(s.h + dy, 4, 100 - s.y);
        if (mode.includes('w')) { const nx = clamp(s.x + dx, 0, s.x + s.w - 5); n.w = s.w + (s.x - nx); n.x = nx; }
        if (mode.includes('n')) { const ny = clamp(s.y + dy, 0, s.y + s.h - 4); n.h = s.h + (s.y - ny); n.y = ny; }
      }
      onChange(n);
    };
    const up = () => { window.removeEventListener('pointermove', move); window.removeEventListener('pointerup', up); };
    window.addEventListener('pointermove', move); window.addEventListener('pointerup', up);
  };

  const handles = ['nw', 'ne', 'sw', 'se', 'n', 's', 'e', 'w'];
  const hpos = {
    nw: { top: -4, left: -4, cursor: 'nwse-resize' }, ne: { top: -4, right: -4, cursor: 'nesw-resize' },
    sw: { bottom: -4, left: -4, cursor: 'nesw-resize' }, se: { bottom: -4, right: -4, cursor: 'nwse-resize' },
    n: { top: -4, left: '50%', marginLeft: -4, cursor: 'ns-resize' }, s: { bottom: -4, left: '50%', marginLeft: -4, cursor: 'ns-resize' },
    e: { right: -4, top: '50%', marginTop: -4, cursor: 'ew-resize' }, w: { left: -4, top: '50%', marginTop: -4, cursor: 'ew-resize' },
  };

  return (
    <div
      onPointerDown={(e) => begin(e, 'move')}
      style={{
        position: 'absolute', left: slot.x + '%', top: slot.y + '%', width: slot.w + '%', height: slot.h + '%',
        border: `${selected ? 2.5 : 2}px ${slot.binding === 'dynamic' ? 'solid' : 'dashed'} ${ty.color}`,
        borderRadius: 5, cursor: 'move', boxSizing: 'border-box',
        background: `color-mix(in oklch, ${ty.color} ${selected ? 14 : 8}%, transparent)`,
        boxShadow: selected ? `0 0 0 3px color-mix(in oklch, ${ty.color} 22%, transparent), var(--sh)` : 'none',
        zIndex: selected ? 20 : (slot.binding === 'fixed' ? 6 : 8), transition: 'box-shadow .12s',
      }}
    >
      {/* ghost content hint */}
      <div style={{ position: 'absolute', inset: 0, display: 'grid', placeItems: 'center', color: ty.color, opacity: .5, overflow: 'hidden', pointerEvents: 'none' }}>
        <Icon name={ty.icon} size={Math.min(26, Math.max(14, slot.h * 4))} />
      </div>
      {/* label tab */}
      <div style={{
        position: 'absolute', top: -11, insetInlineStart: 6, display: 'flex', alignItems: 'center', gap: 5,
        background: ty.color, color: '#fff', fontSize: 10.5, fontWeight: 700, padding: '2px 8px 2px 6px',
        borderRadius: 6, whiteSpace: 'nowrap', boxShadow: 'var(--sh-sm)', pointerEvents: 'none', maxWidth: '95%',
      }}>
        <Icon name={ty.icon} size={11} strokeWidth={2.2} />
        <span style={{ overflow: 'hidden', textOverflow: 'ellipsis' }}>{slot.name || 'ללא שם'}</span>
        {risk && <span style={{ width: 6, height: 6, borderRadius: 99, background: '#fff' }} />}
      </div>
      {/* binding badge */}
      <div style={{
        position: 'absolute', bottom: 4, insetInlineEnd: 5, fontSize: 9, fontWeight: 800, letterSpacing: '.3px',
        padding: '1px 6px', borderRadius: 5, pointerEvents: 'none',
        background: slot.binding === 'dynamic' ? 'color-mix(in oklch, var(--accent) 16%, #fff)' : 'color-mix(in oklch, var(--ink) 8%, #fff)',
        color: slot.binding === 'dynamic' ? 'var(--accent-ink)' : 'var(--ink-2)',
      }}>{slot.binding === 'dynamic' ? 'דינמי' : 'קבוע'}</div>
      {/* resize handles */}
      {selected && handles.map(h => (
        <div key={h} onPointerDown={(e) => begin(e, h)} style={{
          position: 'absolute', width: 9, height: 9, background: '#fff', border: `2px solid ${ty.color}`,
          borderRadius: 2, ...hpos[h], zIndex: 21,
        }} />
      ))}
    </div>
  );
}

/* ---- faint paper backdrop so boxes feel anchored to a real page ---- */
function PaperBackdrop() {
  return (
    <div style={{ position: 'absolute', inset: 0, pointerEvents: 'none', background:
      'repeating-linear-gradient(180deg, transparent, transparent 26px, oklch(0.92 0.004 260 / .5) 26px, oklch(0.92 0.004 260 / .5) 27px)' }} />
  );
}

/* ---- center canvas: page tabs + the A4 page ---- */
function PageCanvas({ pages, curId, setCur, selId, setSel, updateSlot, fileName }) {
  const page = pages.find(p => p.id === curId) || pages[0];
  const canvasRef = React.useRef(null);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', minWidth: 0, background: 'var(--surface-2)', borderInline: '1px solid var(--line)' }}>
      {/* canvas toolbar */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '12px 18px', borderBottom: '1px solid var(--line)', flexShrink: 0 }}>
        <Icon name="filePdf" size={18} style={{ color: 'var(--danger)' }} />
        <span style={{ fontWeight: 700, fontSize: 13 }}>{fileName}</span>
        <div style={{ width: 1, height: 18, background: 'var(--line-2)', margin: '0 4px' }} />
        <div className="seg" style={{ overflowX: 'auto' }}>
          {pages.map(p => (
            <button key={p.id} className={p.id === curId ? 'on' : ''} onClick={() => setCur(p.id)} title={p.name}>
              {p.name} <span style={{ fontFamily: 'var(--mono)', fontSize: 10, opacity: .7 }}>· {p.slots.length}</span>
            </button>
          ))}
        </div>
        <div style={{ marginInlineStart: 'auto', display: 'flex', alignItems: 'center', gap: 7, fontSize: 11.5, color: 'var(--ink-3)', fontWeight: 700 }}>
          <Icon name="move" size={14} /> גרור תיבות · משוך פינות לשינוי גודל
        </div>
      </div>
      {/* page stage */}
      <div style={{ flex: 1, overflow: 'auto', display: 'grid', placeItems: 'center', padding: 28 }}>
        <div ref={canvasRef} onPointerDown={() => setSel(null)} style={{
          position: 'relative', aspectRatio: page.ar || '210 / 297', width: 'auto',
          height: '100%', maxHeight: page.ar === '2 / 1' ? 470 : 720,
          background: page.dark ? '#11151c' : '#fff',
          borderRadius: 6, boxShadow: 'var(--sh-lg)', flexShrink: 0,
        }}>
          {!page.dark && <PaperBackdrop />}
          {page.slots.map(s => (
            <SlotBox key={s.id} slot={s} selected={s.id === selId} canvasRef={canvasRef}
              onSelect={() => setSel(s.id)} onChange={(d) => updateSlot(page.id, s.id, d)} />
          ))}
          {page.slots.length === 0 && (
            <div style={{ position: 'absolute', inset: 0, display: 'grid', placeItems: 'center', color: 'var(--ink-3)', fontSize: 13, fontWeight: 600 }}>
              אין Slots בעמוד זה — צור חדש מהרשימה
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

Object.assign(window, { SlotBox, PageCanvas, confColor });


