/* ============ Template Learning — Compare PDFs + Template Spec summary ============ */

/* verdict for the compare engine: would this slot stay constant across samples? */
function compareVerdict(slot) {
  const constByType = ['logo', 'legal', 'footer', 'header'];
  let v = constByType.includes(slot.type) ? 'const' : 'var';
  // sl6 = spread section title, currently dynamic but identical across Berlingo/Jumpy/C3 Aircross → suggest fixed
  return v;
}

/* ---- mode: compare 2–3 spec PDFs from the same template ---- */
function CompareView({ pages, onApply, onSkip }) {
  const allSlots = pages.flatMap(p => p.slots.map(s => ({ ...s, pageName: p.name, pageId: p.id })));
  const [docs, setDocs] = React.useState([
    { name: 'Berlingo.pdf', base: true },
    null, null,
  ]);
  const [state, setState] = React.useState('setup'); // setup | running | results
  const ready = docs.filter(Boolean).length >= 2;
  const samples = ['Jumpy.pdf', 'C3_Aircross.pdf'];

  const addDoc = () => setDocs(d => {
    const i = d.indexOf(null); if (i === -1) return d;
    const used = d.filter(Boolean).length - 1;
    const copy = [...d]; copy[i] = { name: samples[used] || 'Sample_Spec.pdf' }; return copy;
  });

  const run = () => { setState('running'); setTimeout(() => setState('results'), 1900); };

  const verdicts = allSlots.map(s => {
    const v = compareVerdict(s);
    const cur = s.binding === 'fixed' ? 'const' : 'var';
    return { slot: s, verdict: v, mismatch: v !== cur };
  });
  const changedCount = verdicts.filter(v => v.mismatch).length;

  return (
    <div className="scroll" style={{ flex: 1 }}>
      <div style={{ maxWidth: 1080, margin: '0 auto', padding: '26px 30px 60px' }}>
        <div style={{ marginBottom: 22 }}>
          <h2 style={{ fontSize: 23, fontWeight: 800, letterSpacing: '-.4px', fontFamily: 'var(--display)' }}>השוואת מפרטים — קבוע מול משתנה</h2>
          <p style={{ color: 'var(--ink-2)', fontSize: 14, marginTop: 4, maxWidth: 680 }}>
            העלה 2–3 מפרטים שנוצרו מאותה תבנית. המערכת משווה את האזורים ומסיקה אילו Slots נשארים <b>קבועים</b> בכל המפרטים ואילו <b>משתנים</b> לפי הדגם — וכך מדייקת את התבנית.
          </p>
        </div>

        {/* document tray */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: 14, marginBottom: 20 }}>
          {docs.map((d, i) => d ? (
            <div key={i} className="card" style={{ padding: 16, position: 'relative', borderColor: d.base ? 'var(--accent-line)' : 'var(--line)' }}>
              {d.base && <span style={{ position: 'absolute', top: 12, insetInlineEnd: 12 }} className="chip chip-accent">מקור הניתוח</span>}
              <div style={{ width: 42, height: 52, borderRadius: 6, background: 'var(--surface-3)', display: 'grid', placeItems: 'center', color: 'var(--danger)', marginBottom: 12 }}>
                <Icon name="filePdf" size={24} />
              </div>
              <div style={{ fontWeight: 700, fontSize: 13, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{d.name}</div>
              <div style={{ fontSize: 11.5, color: 'var(--eco)', fontWeight: 700, marginTop: 3, display: 'flex', alignItems: 'center', gap: 5 }}>
                <Icon name="checkCircle" size={13} /> נטען · נותח
              </div>
            </div>
          ) : (
            <button key={i} className="learn-card" onClick={addDoc} disabled={state !== 'setup'}
              style={{ minHeight: 132, borderRadius: 'var(--r-lg)', border: '1.5px dashed var(--line-2)', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 9, color: 'var(--ink-3)', background: 'var(--surface)', opacity: state !== 'setup' ? .5 : 1 }}>
              <div style={{ width: 40, height: 40, borderRadius: 11, background: 'var(--surface-3)', display: 'grid', placeItems: 'center' }}><Icon name="upload" size={19} /></div>
              <span style={{ fontWeight: 700, fontSize: 12.5 }}>הוסף מפרט להשוואה</span>
            </button>
          ))}
        </div>

        {/* action bar */}
        {state !== 'results' && (
          <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 8 }}>
            <button className="btn btn-primary" disabled={!ready || state === 'running'} onClick={run} style={{ opacity: ready ? 1 : .5 }}>
              {state === 'running' ? <><span className="spinner" /> משווה אזורים…</> : <><Icon name="scan" /> נתח קבוע מול משתנה</>}
            </button>
            <button className="btn btn-ghost" onClick={onSkip}><Icon name="chevR" /> חזרה לאישור אזורים</button>
            {!ready && <span style={{ fontSize: 12.5, color: 'var(--ink-3)', fontWeight: 600 }}>נדרשים לפחות 2 מפרטים</span>}
          </div>
        )}

        {/* results */}
        {state === 'results' && (
          <div className="fade-up">
            <div className="card" style={{ padding: 0, overflow: 'hidden', marginBottom: 18 }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '14px 18px', borderBottom: '1px solid var(--line)', background: 'var(--surface-2)' }}>
                <Icon name="checkCircle" size={19} style={{ color: 'var(--eco)' }} />
                <span style={{ fontWeight: 800, fontSize: 14 }}>ההשוואה הושלמה</span>
                <span style={{ fontSize: 12.5, color: 'var(--ink-2)', fontWeight: 600 }}>· {docs.filter(Boolean).length} מפרטים · {allSlots.length} אזורים</span>
                {changedCount > 0 && <span className="chip chip-warn" style={{ marginInlineStart: 'auto' }}>{changedCount} הצעות סיווג</span>}
              </div>
              {/* column header */}
              <div style={{ display: 'grid', gridTemplateColumns: '1.6fr 1.1fr 110px', gap: 10, padding: '9px 18px', fontSize: 11, fontWeight: 800, color: 'var(--ink-3)', borderBottom: '1px solid var(--line)' }}>
                <span>אזור</span><span>השוואת דגימות</span><span style={{ textAlign: 'center' }}>מסקנה</span>
              </div>
              {verdicts.map(({ slot, verdict, mismatch }) => {
                const ty = SLOT_TYPES[slot.type];
                return (
                  <div key={slot.id} style={{ display: 'grid', gridTemplateColumns: '1.6fr 1.1fr 110px', gap: 10, padding: '11px 18px', alignItems: 'center', borderBottom: '1px solid var(--line)' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 9, minWidth: 0 }}>
                      <span style={{ width: 24, height: 24, borderRadius: 6, flexShrink: 0, display: 'grid', placeItems: 'center', background: `color-mix(in oklch, ${ty.color} 14%, #fff)`, color: ty.color }}><Icon name={ty.icon} size={13} /></span>
                      <span style={{ minWidth: 0 }}>
                        <span style={{ display: 'block', fontWeight: 700, fontSize: 12.5, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{slot.name}</span>
                        <span style={{ fontSize: 10.5, color: 'var(--ink-3)', fontWeight: 600 }}>{slot.pageName}</span>
                      </span>
                    </div>
                    {/* sample viz: identical vs differing bars */}
                    <div style={{ display: 'flex', gap: 5 }}>
                      {[0, 1, 2].slice(0, docs.filter(Boolean).length).map(k => (
                        <span key={k} style={{ flex: 1, height: 16, borderRadius: 4, border: '1px solid var(--line)',
                          background: verdict === 'const' ? 'color-mix(in oklch, var(--ink) 9%, #fff)'
                            : `color-mix(in oklch, ${ty.color} ${14 + k * 16}%, #fff)` }} />
                      ))}
                    </div>
                    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 3 }}>
                      <span style={{ display: 'inline-flex', alignItems: 'center', gap: 5, fontSize: 11.5, fontWeight: 800,
                        color: verdict === 'const' ? 'var(--ink-2)' : 'var(--accent-ink)' }}>
                        <Icon name={verdict === 'const' ? 'lock' : 'refresh'} size={13} /> {verdict === 'const' ? 'קבוע' : 'משתנה'}
                      </span>
                      {mismatch && <span style={{ fontSize: 9.5, fontWeight: 800, color: 'oklch(0.5 0.13 60)', background: 'var(--warn-soft)', padding: '1px 6px', borderRadius: 5 }}>שונה מהנוכחי</span>}
                    </div>
                  </div>
                );
              })}
            </div>
            <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
              <button className="btn btn-primary" onClick={() => onApply(verdicts)}><Icon name="check" /> החל סיווג על ה-Slots</button>
              <button className="btn btn-ghost" onClick={onSkip}>חזרה בלי לשנות</button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

/* ---- final: Template Spec report ---- */
function SpecSummary({ pages, name, setName, brand, setBrand, onSave, onOpenEditor }) {
  const all = pages.flatMap(p => p.slots.map(s => ({ ...s, pageName: p.name })));
  const dyn = all.filter(s => s.binding === 'dynamic');
  const fix = all.filter(s => s.binding === 'fixed');
  const req = all.filter(s => s.required);
  const opt = all.filter(s => !s.required);
  const risks = all.map(s => ({ s, r: slotRisk(s) })).filter(x => x.r.length);

  return (
    <div className="scroll" style={{ flex: 1 }}>
      <div style={{ maxWidth: 1080, margin: '0 auto', padding: '26px 30px 70px' }}>
        <div style={{ display: 'flex', alignItems: 'flex-start', gap: 16, marginBottom: 24, flexWrap: 'wrap' }}>
          <div style={{ flex: 1, minWidth: 260 }}>
            <div style={{ display: 'inline-flex', alignItems: 'center', gap: 7, fontSize: 11.5, fontWeight: 800, color: 'var(--eco)', background: 'var(--eco-soft)', padding: '4px 11px', borderRadius: 99, marginBottom: 10 }}>
              <Icon name="checkCircle" size={14} /> מוכן לשמירה
            </div>
            <h2 style={{ fontSize: 25, fontWeight: 800, letterSpacing: '-.5px', fontFamily: 'var(--display)' }}>Template Spec</h2>
            <p style={{ color: 'var(--ink-2)', fontSize: 14, marginTop: 4 }}>סיכום מלא של מה שהמערכת למדה. כך תיווצר כל מפרט עתידי מהתבנית.</p>
          </div>
          <div className="card" style={{ padding: 16, width: 320, flexShrink: 0 }}>
            <PField label="שם התבנית">
              <input className="txt-input" style={{ width: '100%' }} value={name} onChange={e => setName(e.target.value)} />
            </PField>
            <PField label="שיוך למותג">
              <select className="txt-input" style={{ width: '100%' }} value={brand} onChange={e => setBrand(e.target.value)}>
                {window.DB.BRANDS.map(b => <option key={b.id} value={b.id}>{b.name}</option>)}
              </select>
            </PField>
            <button className="btn btn-primary" style={{ width: '100%' }} onClick={onSave}><Icon name="check" /> שמור Template Spec</button>
            {onOpenEditor && <button className="btn btn-ghost" style={{ width: '100%', marginTop: 9 }} onClick={onOpenEditor}><Icon name="edit" /> שמור ופתח בעורך</button>}
          </div>
        </div>

        {/* metric strip */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(6, 1fr)', gap: 12, marginBottom: 20 }}>
          <MetricCard icon="file" tone="var(--accent)" value={pages.length} label="סוגי עמודים" />
          <MetricCard icon="layers" tone="var(--accent)" value={all.length} label="סה״כ Slots" />
          <MetricCard icon="refresh" tone="var(--accent)" value={dyn.length} label="אזורים דינמיים" />
          <MetricCard icon="lock" tone="var(--ink-2)" value={fix.length} label="אזורים קבועים" />
          <MetricCard icon="checkCircle" tone="var(--eco)" value={req.length} label="שדות חובה" />
          <MetricCard icon="bell" tone={risks.length ? 'var(--warn)' : 'var(--eco)'} value={risks.length} label="לבדיקה ידנית" />
        </div>

        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 16, alignItems: 'start' }}>
          {/* page types */}
          <SpecCard title="סוגי עמודים" icon="file" count={pages.length}>
            {pages.map(p => (
              <div key={p.id} style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '9px 0', borderBottom: '1px solid var(--line)' }}>
                <span style={{ fontWeight: 700, fontSize: 13 }}>{p.name}</span>
                <div style={{ marginInlineStart: 'auto', display: 'flex', gap: 4 }}>
                  {p.slots.map(s => <span key={s.id} title={SLOT_TYPES[s.type].label} style={{ width: 18, height: 18, borderRadius: 5, display: 'grid', placeItems: 'center', background: `color-mix(in oklch, ${SLOT_TYPES[s.type].color} 16%, #fff)`, color: SLOT_TYPES[s.type].color }}><Icon name={SLOT_TYPES[s.type].icon} size={11} /></span>)}
                </div>
              </div>
            ))}
          </SpecCard>

          {/* dynamic vs fixed */}
          <SpecCard title="דינמי מול קבוע" icon="refresh">
            <SpecGroupList label="דינמי — ממופה לנתונים" icon="refresh" tone="var(--accent-ink)" items={dyn} />
            <div style={{ height: 12 }} />
            <SpecGroupList label="קבוע — חלק מהתבנית" icon="lock" tone="var(--ink-2)" items={fix} />
          </SpecCard>

          {/* required / optional */}
          <SpecCard title="שדות חובה ואופציונליים" icon="checkCircle">
            <SpecGroupList label="חובה" icon="checkCircle" tone="var(--eco)" items={req} />
            <div style={{ height: 12 }} />
            <SpecGroupList label="אופציונלי" icon="eye" tone="var(--ink-3)" items={opt} />
          </SpecCard>

          {/* risks */}
          <SpecCard title="סיכונים ובדיקה ידנית" icon="bell" tone={risks.length ? 'var(--warn)' : 'var(--eco)'}>
            {risks.length === 0 ? (
              <div style={{ display: 'flex', alignItems: 'center', gap: 9, padding: '12px 0', color: 'var(--eco)', fontWeight: 700, fontSize: 13 }}>
                <Icon name="checkCircle" size={18} /> כל האזורים זוהו בביטחון גבוה
              </div>
            ) : risks.map(({ s, r }) => {
              const ty = SLOT_TYPES[s.type];
              return (
                <div key={s.id} style={{ display: 'flex', alignItems: 'flex-start', gap: 10, padding: '10px 0', borderBottom: '1px solid var(--line)' }}>
                  <span style={{ width: 24, height: 24, borderRadius: 6, flexShrink: 0, display: 'grid', placeItems: 'center', background: 'var(--warn-soft)', color: 'oklch(0.5 0.13 60)' }}><Icon name={ty.icon} size={13} /></span>
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ fontWeight: 700, fontSize: 12.5 }}>{s.name} <span style={{ color: 'var(--ink-3)', fontWeight: 600 }}>· {s.pageName}</span></div>
                    <div style={{ fontSize: 11.5, color: 'oklch(0.5 0.1 60)', fontWeight: 600 }}>{r.join(' · ')}</div>
                  </div>
                  <span style={{ fontFamily: 'var(--mono)', fontSize: 11, fontWeight: 700, color: confColor(s.conf) }}>{s.conf}%</span>
                </div>
              );
            })}
          </SpecCard>
        </div>
      </div>
    </div>
  );
}

function MetricCard({ icon, value, label, tone }) {
  return (
    <div className="card" style={{ padding: '13px 14px' }}>
      <Icon name={icon} size={17} style={{ color: tone }} />
      <div style={{ fontSize: 26, fontWeight: 800, fontFamily: 'var(--display)', letterSpacing: '-.5px', marginTop: 6, lineHeight: 1 }}>{value}</div>
      <div style={{ fontSize: 11.5, color: 'var(--ink-3)', fontWeight: 700, marginTop: 3 }}>{label}</div>
    </div>
  );
}

function SpecCard({ title, icon, count, tone, children }) {
  return (
    <div className="card" style={{ padding: 18 }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 9, marginBottom: 8 }}>
        <Icon name={icon} size={18} style={{ color: tone || 'var(--accent)' }} />
        <h3 style={{ fontSize: 14.5, fontWeight: 800 }}>{title}</h3>
        {count != null && <span className="chip" style={{ height: 22, marginInlineStart: 'auto' }}>{count}</span>}
      </div>
      {children}
    </div>
  );
}

function SpecGroupList({ label, icon, tone, items }) {
  return (
    <div>
      <div style={{ display: 'flex', alignItems: 'center', gap: 6, fontSize: 11.5, fontWeight: 800, color: tone, marginBottom: 7 }}>
        <Icon name={icon} size={13} /> {label} <span style={{ fontFamily: 'var(--mono)', color: 'var(--ink-3)' }}>({items.length})</span>
      </div>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6 }}>
        {items.length === 0 && <span style={{ fontSize: 12, color: 'var(--ink-3)' }}>—</span>}
        {items.map(s => (
          <span key={s.id} style={{ display: 'inline-flex', alignItems: 'center', gap: 5, fontSize: 11.5, fontWeight: 600, padding: '4px 9px', borderRadius: 7, background: 'var(--surface-3)', color: 'var(--ink-2)' }}>
            <span style={{ width: 7, height: 7, borderRadius: 2, background: SLOT_TYPES[s.type].color }} /> {s.name}
          </span>
        ))}
      </div>
    </div>
  );
}

Object.assign(window, { CompareView, SpecSummary, MetricCard, SpecCard, SpecGroupList });


/* ===== screen_learn.jsx ===== */

/* ============ Template Learning — orchestrator (scan → review → compare → spec) ============ */
function ScreenLearn({ go }) {
  const [phase, setPhase] = React.useState('idle'); // idle | scanning | review | compare | spec
  const [reached, setReached] = React.useState(0);
  const [pages, setPages] = React.useState(buildInitialPages);
  const [curId, setCur] = React.useState('pg-cover');
  const [selId, setSel] = React.useState(null);
  const [name, setName] = React.useState('Citroën · Square Spread');
  const [brand, setBrand] = React.useState('citroen');
  const [detected, setDetected] = React.useState(0);
  // which real scanned spec is being learned (drives the file name + what opens in the editor)
  const [learnSource, setLearnSource] = React.useState('IMPORTC3');
  const learned = (window.IMPORTS || []).find(it => it.key === learnSource) || {};
  const learnFile = (window[learnSource] && window[learnSource].source) || 'Berlingo.pdf';
  const beginScan = (key) => { if (key) { setLearnSource(key); const it = (window.IMPORTS || []).find(i => i.key === key); if (it) { setName(it.model + ' · תבנית סרוקה'); setBrand(it.brand); } } goPhase('scanning'); };

  const order = ['idle', 'scanning', 'review', 'compare', 'spec'];
  const goPhase = (p) => { setPhase(p); setReached(r => Math.max(r, order.indexOf(p))); const sc = document.querySelector('.lrn-scroll'); if (sc) sc.scrollTop = 0; };

  const coverSlots = pages.find(p => p.id === 'pg-cover').slots;
  React.useEffect(() => {
    if (phase === 'scanning') {
      setDetected(0);
      const timers = coverSlots.map((_, i) => setTimeout(() => setDetected(d => Math.max(d, i + 1)), 600 + i * 480));
      return () => timers.forEach(clearTimeout);
    }
  }, [phase]);

  /* ---- slot mutations ---- */
  const updateSlot = (pageId, slotId, patch) => setPages(ps => ps.map(p => p.id !== pageId ? p : { ...p, slots: p.slots.map(s => s.id === slotId ? { ...s, ...patch } : s) }));
  const addSlot = (pageId) => {
    const id = newSlotId();
    const slot = { id, name: 'Slot חדש', type: 'text', x: 30, y: 40, w: 36, h: 12, binding: 'dynamic', required: false, source: 'ידני', conf: 100, auto: false, notes: '' };
    setPages(ps => ps.map(p => p.id === pageId ? { ...p, slots: [...p.slots, slot] } : p));
    setCur(pageId); setSel(id);
  };
  const deleteSlot = (slotId) => { setPages(ps => ps.map(p => ({ ...p, slots: p.slots.filter(s => s.id !== slotId) }))); setSel(null); };
  const applyCompare = (verdicts) => {
    const map = {}; verdicts.forEach(v => map[v.slot.id] = v.verdict);
    setPages(ps => ps.map(p => ({ ...p, slots: p.slots.map(s => map[s.id] ? { ...s, binding: map[s.id] === 'const' ? 'fixed' : 'dynamic' } : s) })));
    goPhase('review');
  };

  const curPage = pages.find(p => p.id === curId) || pages[0];
  const selSlot = curPage.slots.find(s => s.id === selId) || pages.flatMap(p => p.slots).find(s => s.id === selId) || null;
  const selPageName = (pages.find(p => p.slots.some(s => s.id === selId)) || {}).name || '';

  return (
    <div style={{ flex: 1, minHeight: 0, display: 'flex', flexDirection: 'column' }}>
      <StepBar phase={phase} reached={reached} onGo={goPhase} onBack={() => go('templates')} />

      {/* ---- idle / scanning live in a centered scroll ---- */}
      {(phase === 'idle' || phase === 'scanning') && (
        <div className="scroll lrn-scroll" style={{ flex: 1 }}>
          <div style={{ maxWidth: 1080, margin: '0 auto', padding: '24px 30px 60px' }}>
            <div style={{ marginBottom: 22 }}>
              <h2 style={{ fontSize: 23, fontWeight: 800, letterSpacing: '-.4px', fontFamily: 'var(--display)' }}>לימוד תבנית מ-PDF</h2>
              <p style={{ color: 'var(--ink-2)', fontSize: 14, marginTop: 4, maxWidth: 680 }}>העלה מפרט קיים. המערכת מזהה את מבנה העמודים והאזורים כהצעה ראשונית — ולאחר מכן תאשר ותתקן אותם ידנית כדי לבנות Template Spec מדויק.</p>
            </div>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 340px', gap: 22, alignItems: 'start' }}>
              <div className="card" style={{ padding: 22, background: 'var(--surface-2)' }}>
                {phase === 'idle' ? <UploadPdf onUpload={beginScan} /> : (
                  <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 9, marginBottom: 16, alignSelf: 'flex-start' }}>
                      <Icon name="filePdf" size={20} style={{ color: 'var(--danger)' }} />
                      <span style={{ fontWeight: 700, fontSize: 14 }}>{learnFile}</span>
                      <span className="chip" style={{ height: 22 }}>4 סוגי עמודים · ספרד</span>
                    </div>
                    <div style={{ position: 'relative', width: 400, height: 400, background: '#11151c', borderRadius: 6, boxShadow: 'var(--sh-lg)', overflow: 'hidden' }}>
                      <DocSkeleton />
                      {detected < coverSlots.length && (
                        <div style={{ position: 'absolute', left: 0, right: 0, height: 3, background: 'linear-gradient(90deg, transparent, var(--accent), transparent)', boxShadow: '0 0 16px 3px oklch(0.56 0.16 256 / .6)', animation: 'scanline 2.6s linear infinite', top: 0 }} />
                      )}
                      {coverSlots.map((r, i) => i < detected && (
                        <div key={r.id} className="pop" style={{ position: 'absolute', left: r.x + '%', top: r.y + '%', width: r.w + '%', height: r.h + '%',
                          border: `2px solid ${SLOT_TYPES[r.type].color}`, borderRadius: 5, background: `color-mix(in oklch, ${SLOT_TYPES[r.type].color} 12%, transparent)` }}>
                          <span style={{ position: 'absolute', top: -10, insetInlineStart: 6, background: SLOT_TYPES[r.type].color, color: '#fff', fontSize: 9.5, fontWeight: 700, padding: '2px 7px', borderRadius: 5, whiteSpace: 'nowrap' }}>{SLOT_TYPES[r.type].label}</span>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </div>

              <div className="card" style={{ padding: 18, position: 'sticky', top: 0 }}>
                <h3 style={{ fontSize: 14.5, fontWeight: 800, marginBottom: 14, display: 'flex', alignItems: 'center', gap: 8 }}>
                  <Icon name="scan" size={18} style={{ color: 'var(--accent)' }} /> זיהוי אוטומטי
                </h3>
                {phase === 'idle' ? <EmptyHint icon="file" title="ממתין להעלאה" text="העלה PDF כדי להתחיל בניתוח" /> : (
                  <div style={{ display: 'flex', flexDirection: 'column', gap: 9 }}>
                    <DetectRow label="סוגי עמודים" value="4 (שער · ספרד · אבזור · גב)" done={detected >= 1} />
                    <DetectRow label="גודל עמוד" value="595² · ספרד 1191×595" done={detected >= 1} />
                    <DetectRow label="אזורים שזוהו" value={pages.reduce((n, p) => n + p.slots.length, 0) + ' אזורים'} done={detected >= 3} />
                    <DetectRow label="כיוון טקסט" value="RTL · עברית" done={detected >= 4} />
                    <DetectRow label="צבע מבטא" value="#00ACBA" swatch="#00ACBA" done={detected >= 4} />
                    <DetectRow label="טיפוגרפיה" value="CitroenType · Hebrew" done={detected >= coverSlots.length} />
                    {detected >= coverSlots.length && (
                      <button className="btn btn-primary fade-up" style={{ width: '100%', marginTop: 8 }} onClick={() => goPhase('review')}>
                        <Icon name="arrowL" /> אישור וסימון אזורים
                      </button>
                    )}
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      )}

      {/* ---- review: 3-column editor ---- */}
      {phase === 'review' && (
        <div style={{ flex: 1, minHeight: 0, display: 'grid', gridTemplateColumns: '262px minmax(0, 1fr) 322px' }}>
          <SlotRail pages={pages} curId={curId} setCur={setCur} selId={selId} setSel={setSel} addSlot={addSlot} />
          <PageCanvas pages={pages} curId={curId} setCur={setCur} selId={selId} setSel={setSel} updateSlot={updateSlot} fileName={learnFile} />
          <SlotProps slot={selSlot} pageName={selPageName} onChange={(patch) => updateSlot(pages.find(p => p.slots.some(s => s.id === selId)).id, selId, patch)} onDelete={() => deleteSlot(selId)} />
        </div>
      )}

      {phase === 'compare' && <CompareView pages={pages} onApply={applyCompare} onSkip={() => goPhase('review')} />}
      {phase === 'spec' && <SpecSummary pages={pages} name={name} setName={setName} brand={brand} setBrand={setBrand} onSave={() => go('templates')} onOpenEditor={() => go('editor', { source: learnSource })} />}
    </div>
  );
}

/* ---- progress stepper + contextual actions ---- */
function StepBar({ phase, reached, onGo, onBack }) {
  const order = ['idle', 'scanning', 'review', 'compare', 'spec'];
  const steps = [
    { p: 'idle', label: 'העלאה', icon: 'upload' },
    { p: 'scanning', label: 'סריקה', icon: 'scan' },
    { p: 'review', label: 'אישור וסימון', icon: 'edit' },
    { p: 'compare', label: 'השוואה', icon: 'versions', opt: true },
    { p: 'spec', label: 'Template Spec', icon: 'cube' },
  ];
  const curIdx = order.indexOf(phase);
  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: 14, padding: '11px 20px', borderBottom: '1px solid var(--line)', background: 'var(--surface)', flexShrink: 0 }}>
      <button onClick={onBack} className="icon-btn" title="חזרה לתבניות" style={{ width: 32, height: 32 }}><Icon name="chevR" size={18} /></button>
      <div style={{ display: 'flex', alignItems: 'center', gap: 4, flex: 1, overflowX: 'auto' }}>
        {steps.map((s, i) => {
          const idx = order.indexOf(s.p);
          const done = idx < curIdx, active = idx === curIdx;
          const clickable = idx <= reached && !active;
          return (
            <React.Fragment key={s.p}>
              {i > 0 && <div style={{ width: 18, height: 2, borderRadius: 2, background: idx <= curIdx ? 'var(--accent)' : 'var(--line-2)', flexShrink: 0 }} />}
              <button onClick={() => clickable && onGo(s.p)} disabled={!clickable && !active} title={s.label}
                style={{ display: 'flex', alignItems: 'center', gap: 7, padding: '6px 11px', borderRadius: 9, flexShrink: 0,
                  background: active ? 'var(--accent-soft)' : 'transparent', cursor: clickable ? 'pointer' : 'default' }}>
                <span style={{ width: 22, height: 22, borderRadius: 99, flexShrink: 0, display: 'grid', placeItems: 'center', fontSize: 11, fontWeight: 800,
                  background: active ? 'var(--accent)' : done ? 'var(--eco)' : 'var(--surface-3)',
                  color: active || done ? '#fff' : 'var(--ink-3)' }}>
                  {done ? <Icon name="check" size={13} strokeWidth={3} /> : <Icon name={s.icon} size={12} />}
                </span>
                <span style={{ fontSize: 12.5, fontWeight: 700, color: active ? 'var(--accent-ink)' : done ? 'var(--ink)' : 'var(--ink-3)', whiteSpace: 'nowrap' }}>
                  {s.label}{s.opt && <span style={{ fontSize: 10, color: 'var(--ink-3)', fontWeight: 600 }}> · רשות</span>}
                </span>
              </button>
            </React.Fragment>
          );
        })}
      </div>
      {/* contextual primary actions */}
      {phase === 'review' && (
        <div style={{ display: 'flex', alignItems: 'center', gap: 9, flexShrink: 0 }}>
          <button className="btn btn-ghost btn-sm" onClick={() => onGo('compare')}><Icon name="versions" size={15} /> השוואת PDFים</button>
          <button className="btn btn-primary btn-sm" onClick={() => onGo('spec')}>סיכום Template Spec <Icon name="arrowL" size={15} /></button>
        </div>
      )}
      {phase === 'compare' && (
        <button className="btn btn-primary btn-sm" onClick={() => onGo('spec')} style={{ flexShrink: 0 }}>דלג ל-Template Spec <Icon name="arrowL" size={15} /></button>
      )}
    </div>
  );
}

function UploadPdf({ onUpload }) {
  const [over, setOver] = React.useState(false);
  const specs = window.IMPORTS || [];
  return (
    <div onDragOver={e => { e.preventDefault(); setOver(true); }} onDragLeave={() => setOver(false)} onDrop={e => { e.preventDefault(); setOver(false); onUpload(); }}
      style={{ minHeight: 460, borderRadius: 14, border: `2px dashed ${over ? 'var(--accent)' : 'var(--line-2)'}`, background: over ? 'var(--accent-soft)' : 'var(--surface)', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 18, padding: 24, transition: '.15s' }}>
      <div style={{ width: 70, height: 70, borderRadius: 20, background: 'var(--accent-soft)', display: 'grid', placeItems: 'center', color: 'var(--accent)' }}>
        <Icon name="upload" size={32} />
      </div>
      <div style={{ textAlign: 'center' }}>
        <div style={{ fontWeight: 800, fontSize: 17 }}>גרור PDF של מפרט קיים</div>
        <div style={{ color: 'var(--ink-3)', fontSize: 13.5, marginTop: 4 }}>או בחר מפרט סרוק קיים ללימוד התבנית שלו</div>
      </div>
      {/* pick a real scanned spec to learn from */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, minmax(0,1fr))', gap: 9, width: '100%', maxWidth: 520 }}>
        {specs.map(it => (
          <button key={it.key} className="card pick-card" onClick={() => onUpload(it.key)}
            style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '11px 13px', textAlign: 'start' }}>
            <Icon name="filePdf" size={18} style={{ color: 'var(--danger)', flexShrink: 0 }} />
            <span style={{ fontWeight: 700, fontSize: 13, flex: 1, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{it.model}</span>
            <Icon name="chevL" size={15} style={{ color: 'var(--ink-3)' }} />
          </button>
        ))}
      </div>
    </div>
  );
}

function DocSkeleton() {
  return <div style={{ padding: '7%', height: '100%' }}>
    <div style={{ height: '46%', background: 'linear-gradient(120deg,#1B4FA0,#2E6BD0)', borderRadius: 4, marginBottom: '5%', opacity: .9 }} />
    <div style={{ height: 14, width: '55%', background: 'rgba(255,255,255,.85)', borderRadius: 3, marginBottom: 10 }} />
    <div style={{ height: 8, width: '42%', background: 'rgba(255,255,255,.4)', borderRadius: 3, marginBottom: 24 }} />
    <div style={{ display: 'flex', gap: 8 }}>
      {[0, 1, 2].map(i => <div key={i} style={{ height: 22, width: 64, background: 'rgba(255,255,255,.18)', borderRadius: 99 }} />)}
    </div>
  </div>;
}

function DetectRow({ label, value, done, swatch }) {
  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '8px 0', borderBottom: '1px solid var(--line)', opacity: done ? 1 : .35, transition: 'opacity .3s' }}>
      <div style={{ width: 18, height: 18, borderRadius: 99, flexShrink: 0, background: done ? 'var(--eco)' : 'var(--surface-3)', display: 'grid', placeItems: 'center' }}>
        {done ? <Icon name="check" size={11} strokeWidth={3} style={{ color: '#fff' }} /> : <span style={{ width: 5, height: 5, borderRadius: 99, background: 'var(--ink-3)' }} />}
      </div>
      <span style={{ fontSize: 13, color: 'var(--ink-2)', fontWeight: 600 }}>{label}</span>
      <span style={{ marginInlineStart: 'auto', display: 'flex', alignItems: 'center', gap: 6, fontSize: 12.5, fontWeight: 700, fontFamily: swatch ? 'var(--mono)' : 'inherit' }}>
        {swatch && <span style={{ width: 12, height: 12, borderRadius: 3, background: swatch, border: '1px solid rgba(0,0,0,.1)' }} />}
        {done ? value : '…'}
      </span>
    </div>
  );
}

Object.assign(window, { ScreenLearn, StepBar, UploadPdf, DocSkeleton, DetectRow });


/* ===== screen_editor_panels.jsx ===== */

/* ============ Editor side panels ============ */
const BLOCK_LABELS = {
  image: 'תמונה', logo: 'לוגו', panel: 'פאנל רקע', heading: 'כותרת', subheading: 'כותרת משנה',
  paragraph: 'פסקה', eyebrow: 'תווית עליונה', chips: 'תגיות גרסה', kpi: 'נתוני מפתח',
  specTable: 'טבלת מפרט', colorGrid: 'גלריית צבעים', wheelGrid: 'חישוקים',
  safetyList: 'רשימת בטיחות', pollutionScale: 'סולם זיהום', stars: 'דירוג כוכבים',
};
const BLOCK_ICONS = {
  image: 'image', logo: 'brand', panel: 'columns', heading: 'text', subheading: 'text', paragraph: 'align',
  eyebrow: 'type2', chips: 'list', kpi: 'gauge', specTable: 'table', colorGrid: 'palette',
  wheelGrid: 'wheel', safetyList: 'shield', pollutionScale: 'leaf', stars: 'star',
};
const TEXT_TYPES = ['heading', 'subheading', 'paragraph', 'eyebrow', 'logo'];
const SWATCHES = ['#16181d', '#ffffff', '#52555c', 'oklch(0.56 0.16 256)', 'oklch(0.6 0.13 158)', '#8a8d94', 'rgba(255,255,255,.7)', '#2E4A78'];

function PSection({ title, children, action }) {
  return <div style={{ marginBottom: 18 }}>
    <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 9 }}>
      <span style={{ fontSize: 11.5, fontWeight: 800, color: 'var(--ink-3)', letterSpacing: '.4px' }}>{title}</span>
      {action}
    </div>
    {children}
  </div>;
}

function NumField({ label, value, onChange }) {
  return <div style={{ flex: 1 }}>
    <div style={{ position: 'relative' }}>
      <span style={{ position: 'absolute', insetInlineStart: 9, top: '50%', transform: 'translateY(-50%)', fontSize: 11, fontWeight: 700, color: 'var(--ink-3)', pointerEvents: 'none' }}>{label}</span>
      <input type="number" value={Math.round(value)} onChange={e => onChange(+e.target.value)}
        style={{ width: '100%', height: 34, paddingInlineStart: 26, paddingInlineEnd: 8, border: '1px solid var(--line-2)', borderRadius: 8, fontSize: 12.5, fontWeight: 700, fontFamily: 'var(--mono)', background: 'var(--surface)', color: 'var(--ink)', outline: 'none' }} />
    </div>
  </div>;
}

function PropsPanel({ block, update, onDup, onDel }) {
  const isText = TEXT_TYPES.includes(block.type);
  const dynamic = ['specTable', 'colorGrid', 'wheelGrid', 'safetyList', 'pollutionScale', 'kpi'].includes(block.type);
  return (
    <div>
      {/* header */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '10px 0 16px', borderBottom: '1px solid var(--line)', marginBottom: 16 }}>
        <div style={{ width: 34, height: 34, borderRadius: 9, background: 'var(--accent-soft)', display: 'grid', placeItems: 'center', color: 'var(--accent)' }}>
          <Icon name={BLOCK_ICONS[block.type] || 'cube'} size={18} />
        </div>
        <div style={{ flex: 1 }}>
          <div style={{ fontWeight: 800, fontSize: 14 }}>{BLOCK_LABELS[block.type] || block.type}</div>
          <div style={{ fontSize: 11, color: 'var(--ink-3)', fontFamily: 'var(--mono)' }}>{block.id}</div>
        </div>
        <button className="icon-btn" style={{ width: 30, height: 30 }} onClick={onDup}><Icon name="copy" size={15} /></button>
        <button className="icon-btn" style={{ width: 30, height: 30, color: 'var(--danger)' }} onClick={onDel}><Icon name="trash" size={15} /></button>
      </div>

      {/* text content */}
      {isText && (
        <PSection title="טקסט">
          <textarea value={block.text} onChange={e => update({ text: e.target.value })} dir="rtl"
            style={{ width: '100%', minHeight: block.type === 'paragraph' ? 88 : 44, padding: '9px 11px', border: '1px solid var(--line-2)', borderRadius: 9, fontSize: 13.5, fontFamily: 'var(--font)', lineHeight: 1.5, resize: 'vertical', outline: 'none', background: 'var(--surface)', color: 'var(--ink)' }} />
        </PSection>
      )}

      {block.type === 'chips' && (
        <PSection title="גרסאות">
          <input value={block.items.join(', ')} onChange={e => update({ items: e.target.value.split(',').map(s => s.trim()) })} dir="rtl"
            style={{ width: '100%', height: 36, padding: '0 11px', border: '1px solid var(--line-2)', borderRadius: 9, fontSize: 13, outline: 'none', background: 'var(--surface)' }} />
        </PSection>
      )}

      {/* font size */}
      {block.size != null && (
        <PSection title="גודל גופן">
          <div style={{ display: 'flex', alignItems: 'center', gap: 11 }}>
            <input type="range" min="11" max="110" value={block.size} onChange={e => update({ size: +e.target.value })} style={{ flex: 1, accentColor: 'var(--accent)' }} />
            <span style={{ fontFamily: 'var(--mono)', fontSize: 12.5, fontWeight: 700, width: 38, textAlign: 'center' }}>{block.size}</span>
          </div>
        </PSection>
      )}

      {/* color */}
      {(isText || block.type === 'eyebrow') && (
        <PSection title="צבע">
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 7 }}>
            {SWATCHES.map(c => (
              <button key={c} onClick={() => update({ color: c })} style={{
                width: 28, height: 28, borderRadius: 8, background: c, cursor: 'pointer',
                border: block.color === c ? '2px solid var(--accent)' : '1px solid var(--line-2)',
                boxShadow: block.color === c ? '0 0 0 2px var(--accent-soft)' : 'none',
                outline: c.includes('255,255,255') || c === '#ffffff' ? '1px solid var(--line)' : 'none', outlineOffset: -1,
              }} />
            ))}
          </div>
        </PSection>
      )}

      {/* image options */}
      {block.type === 'image' && (
        <>
          <PSection title="תיאור התמונה">
            <input value={block.label} onChange={e => update({ label: e.target.value })} dir="rtl"
              style={{ width: '100%', height: 36, padding: '0 11px', border: '1px solid var(--line-2)', borderRadius: 9, fontSize: 13, outline: 'none', background: 'var(--surface)' }} />
          </PSection>
          <PSection title="רקע">
            <div className="seg" style={{ width: '100%' }}>
              <button className={block.tone === 'light' ? 'on' : ''} onClick={() => update({ tone: 'light' })} style={{ flex: 1 }}>בהיר</button>
              <button className={block.tone === 'dark' ? 'on' : ''} onClick={() => update({ tone: 'dark' })} style={{ flex: 1 }}>כהה</button>
            </div>
          </PSection>
          <button className="btn btn-ghost btn-sm" style={{ width: '100%', marginBottom: 18 }}><Icon name="image" size={15} /> החלף תמונה</button>
        </>
      )}

      {dynamic && (
        <PSection title="מקור נתונים">
          <div style={{ padding: 12, background: 'var(--accent-soft)', borderRadius: 10, fontSize: 12.5, color: 'var(--accent-ink)', display: 'flex', gap: 9, lineHeight: 1.45 }}>
            <Icon name="table" size={16} style={{ flexShrink: 0, marginTop: 1 }} />
            תוכן זה מתעדכן אוטומטית מנתוני המפרט. עריכת הנתונים תשתקף בכל העמודים.
          </div>
          <button className="btn btn-ghost btn-sm" style={{ width: '100%', marginTop: 9 }}><Icon name="edit" size={15} /> ערוך נתונים</button>
        </PSection>
      )}

      {/* position */}
      <PSection title="מיקום וגודל">
        <div style={{ display: 'flex', gap: 8, marginBottom: 8 }}>
          <NumField label="X" value={block.x} onChange={v => update({ x: v })} />
          <NumField label="Y" value={block.y} onChange={v => update({ y: v })} />
        </div>
        <div style={{ display: 'flex', gap: 8 }}>
          <NumField label="W" value={block.w} onChange={v => update({ w: v })} />
          <NumField label="H" value={block.h} onChange={v => update({ h: v })} />
        </div>
      </PSection>

      <div style={{ padding: 11, background: 'var(--surface-3)', borderRadius: 10, fontSize: 11.5, color: 'var(--ink-3)', display: 'flex', alignItems: 'center', gap: 7 }}>
        <Icon name="move" size={14} /> גרור את האלמנט על הקנבס כדי למקם אותו
      </div>
    </div>
  );
}

function fontLabel(f) {
  if (!f) return 'לא מוגדר';
  if (/Peugeot/i.test(f)) return 'Peugeot New (מוטמע)';
  if (/Citroen/i.test(f)) return 'Citroën Type';
  if (/Assistant|Heebo/i.test(f)) return 'Assistant (ברירת מחדל)';
  return f;
}

function QARow({ ok, warn, label }) {
  const color = warn ? 'var(--warn)' : ok ? 'var(--eco)' : 'var(--ink-3)';
  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: 12, color: 'var(--ink-2)', padding: '3px 0' }}>
      <Icon name={warn ? 'alert' : 'check'} size={13} style={{ color, flexShrink: 0 }} />
      <span style={{ flex: 1 }}>{label}</span>
    </div>
  );
}

/* Import diagnostics: fidelity status + per-page QA warnings */
function ImportInfo({ page }) {
  const w = page.importWarnings || [];
  const errs = w.filter(x => x.level === 'error');
  const warns = w.filter(x => x.level !== 'error');
  const q = page.visualQuality != null ? page.visualQuality : 100;
  const qColor = q >= 85 ? 'var(--eco)' : q >= 60 ? 'var(--warn)' : 'var(--danger)';
  return (
    <div style={{ marginBottom: 18 }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 10 }}>
        <span className="chip chip-eco" style={{ height: 24 }}><Icon name="scan" size={13} /> מיובא מ-PDF</span>
        <span style={{ fontSize: 11, color: 'var(--ink-3)', fontFamily: 'var(--mono)' }} dir="ltr">{page.sourcePdf || '—'} · p{page.sourcePageNumber || '?'}</span>
      </div>

      {/* fidelity quality bar */}
      <div style={{ marginBottom: 12 }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 11, fontWeight: 700, color: 'var(--ink-3)', marginBottom: 5 }}>
          <span>איכות ייבוא</span><span style={{ color: qColor, fontFamily: 'var(--mono)' }}>{q}%</span>
        </div>
        <div style={{ height: 6, borderRadius: 99, background: 'var(--surface-3)', overflow: 'hidden' }}>
          <div style={{ width: q + '%', height: '100%', background: qColor, borderRadius: 99 }} />
        </div>
      </div>

      <PSection title="שכבות העמוד">
        <QARow ok label="רקע PDF מקורי זמין (מקור אמת ויזואלי)" warn={!page.originalPreviewSrc} />
        <QARow ok label={`שכבת עריכה: ${page.blocks.length} בלוקים`} />
        <QARow ok label={`גופן מותג: ${fontLabel(page.brandFont)}`} warn={!page.brandFont} />
        <QARow ok label="סדר שכבות דטרמיניסטי (zIndex)" />
      </PSection>

      <PSection title={`בדיקת איכות · ${w.length ? w.length + ' התראות' : 'נקי'}`}>
        {w.length === 0
          ? <QARow ok label="לא נמצאו בעיות בעמוד זה" />
          : <div style={{ display: 'flex', flexDirection: 'column', gap: 3 }}>
              {errs.concat(warns).map((x, i) => (
                <div key={i} style={{ display: 'flex', gap: 8, alignItems: 'flex-start', padding: '7px 9px', borderRadius: 8, background: x.level === 'error' ? 'var(--danger-soft)' : 'var(--warn-soft)' }}>
                  <Icon name="alert" size={13} style={{ color: x.level === 'error' ? 'var(--danger)' : 'oklch(0.5 0.13 60)', flexShrink: 0, marginTop: 1 }} />
                  <span style={{ fontSize: 12, color: 'var(--ink-2)', lineHeight: 1.35 }}>{x.msg}{x.block ? ` · ${x.block}` : ''}</span>
                </div>
              ))}
            </div>}
        <div style={{ marginTop: 9, padding: 10, background: 'var(--surface-3)', borderRadius: 9, fontSize: 11.5, color: 'var(--ink-3)', lineHeight: 1.5 }}>
          התראות חפיפה/חריגה משפיעות על שכבת העריכה בלבד — תצוגת "מקור" נשארת נאמנה ל-PDF.
        </div>
      </PSection>
      <div style={{ height: 1, background: 'var(--line)', margin: '4px 0 16px' }} />
    </div>
  );
}

function PageProps({ page, go }) {
  const bgs = ['#ffffff', '#0E1116', '#f5f6f8', '#16181d'];
  const imp = page.kind === 'import';
  return (
    <div>
      <div style={{ padding: '10px 0 16px', borderBottom: '1px solid var(--line)', marginBottom: 16 }}>
        <div style={{ fontWeight: 800, fontSize: 15 }}>{page.name}</div>
        <div style={{ fontSize: 12, color: 'var(--ink-3)', marginTop: 2 }}>{page.blocks.length} אלמנטים · <span dir="ltr" style={{ display: 'inline-block', fontFamily: 'var(--mono)' }}>{page.w || 1191}×{page.h || 595}</span></div>
      </div>
      {imp && <ImportInfo page={page} />}
      <PSection title="רקע העמוד">
        <div style={{ display: 'flex', gap: 8 }}>
          {bgs.map(c => <div key={c} style={{ width: 36, height: 36, borderRadius: 9, background: c, border: page.bg === c ? '2px solid var(--accent)' : '1px solid var(--line-2)', cursor: 'pointer' }} />)}
        </div>
      </PSection>
      <PSection title="הוסף אלמנט">
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8 }}>
          {[['text', 'טקסט'], ['image', 'תמונה'], ['table', 'טבלה'], ['palette', 'צבעים'], ['shield', 'בטיחות'], ['columns', 'נתונים']].map(t => (
            <button key={t[1]} className="btn btn-ghost btn-sm" style={{ justifyContent: 'flex-start' }}><Icon name={t[0]} size={15} /> {t[1]}</button>
          ))}
        </div>
      </PSection>
      <div style={{ padding: 13, background: 'var(--surface-3)', borderRadius: 11, fontSize: 12.5, color: 'var(--ink-2)', lineHeight: 1.5 }}>
        בחר אלמנט על הקנבס כדי לערוך את התוכן, הצבע, הגודל והמיקום שלו.
      </div>
    </div>
  );
}

function LayersPanel({ page, sel, setSel, hidden, setHidden }) {
  hidden = hidden || {};
  setHidden = setHidden || (() => {});
  return (
    <div>
      <PSection title={`שכבות · ${page.blocks.length}`}>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 3 }}>
          {[...page.blocks].reverse().map(b => (
            <div key={b.id} onClick={() => setSel(b.id)} className="layer-row"
              style={{ display: 'flex', alignItems: 'center', gap: 9, padding: '8px 9px', borderRadius: 8, cursor: 'pointer',
                background: sel === b.id ? 'var(--accent-soft)' : 'transparent' }}>
              <Icon name={BLOCK_ICONS[b.type] || 'cube'} size={15} style={{ color: sel === b.id ? 'var(--accent)' : 'var(--ink-3)', flexShrink: 0 }} />
              <span style={{ flex: 1, fontSize: 12.5, fontWeight: sel === b.id ? 700 : 600, color: sel === b.id ? 'var(--accent-ink)' : 'var(--ink)', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                {b.text ? b.text.slice(0, 18) : BLOCK_LABELS[b.type] || b.type}
              </span>
              <button onClick={e => { e.stopPropagation(); setHidden(h => ({ ...h, [b.id]: !h[b.id] })); }} style={{ color: 'var(--ink-3)', opacity: hidden[b.id] ? .5 : 1 }}>
                <Icon name={hidden[b.id] ? 'eyeOff' : 'eye'} size={14} />
              </button>
            </div>
          ))}
        </div>
      </PSection>
    </div>
  );
}

Object.assign(window, { PropsPanel, PageProps, LayersPanel });


/* ===== screen_editor.jsx ===== */

/* ============ Visual Editor — the centerpiece ============ */
const { PAGE_W: EW, PAGE_H: EH } = window.DB;

function clone(x) { return JSON.parse(JSON.stringify(x)); }

function ScreenEditor({ go, source }) {
  const imported = source && source !== 'template' && window[source];
  const [pages, setPages] = React.useState(() => clone(imported ? window[source].pages : window.DB.CATALOG_PAGES));
  const [cur, setCur] = React.useState(0);
  const [sel, setSel] = React.useState(null);
  const [editing, setEditing] = React.useState(null); // block id being text-edited inline
  const [hidden, setHidden] = React.useState({}); // block ids hidden via the Layers panel
  const [scale, setScale] = React.useState(0.46);
  const [tab, setTab] = React.useState('design'); // design | layers
  const [preview, setPreview] = React.useState(false);
  // Imported pages open in 'editable': the original PDF render shows as the base
  // layer and the overlay blocks are invisible click-to-edit hotspots on top, so
  // the page looks exactly like the PDF (no doubled text) yet stays editable.
  // original | editable | reconstructed | compare
  const [viewMode, setViewMode] = React.useState('editable');
  const [saved, setSaved] = React.useState('נשמר');
  const [hist, setHist] = React.useState([]);
  const drag = React.useRef(null);

  const page = pages[cur];
  const block = page.blocks.find(b => b.id === sel);
  const isImport = page.kind === 'import';
  // In Original view there are no overlay blocks to select/move.
  const canEdit = !preview && !(isImport && viewMode === 'original');
  const pageWarnings = isImport ? (page.importWarnings || []) : [];

  const pushHist = () => setHist(h => [...h.slice(-20), clone(pages)]);
  const undo = () => setHist(h => { if (!h.length) return h; const last = h[h.length - 1]; setPages(last); return h.slice(0, -1); });

  const markDirty = () => { setSaved('שומר…'); setTimeout(() => setSaved('נשמר'), 700); };

  const updateBlock = (patch) => {
    // _dirty marks the block edited so the renderer reveals it over the original (any
    // property change — size, colour, position — becomes visible, not just text/move).
    setPages(ps => ps.map((p, i) => i !== cur ? p : { ...p, blocks: p.blocks.map(b => b.id === sel ? { ...b, ...patch, _dirty: true } : b) }));
    markDirty();
  };

  // inline text edit (double-click on canvas) — commits on blur, preserves styling
  const editBlockText = (id, text) => {
    setPages(ps => ps.map((p, i) => i !== cur ? p : { ...p, blocks: p.blocks.map(b => b.id === id ? { ...b, text } : b) }));
    markDirty();
  };
  const startEdit = (id) => { setSel(id); setEditing(id); };

  // drag to move
  const onSelect = (id, e) => {
    if (preview) return;
    setSel(id);
    if (editing && editing !== id) setEditing(null);  // leave inline edit when picking another block
    const b = page.blocks.find(x => x.id === id);
    if (!b || !e) return;
    pushHist();
    drag.current = { type: 'move', id, sx: e.clientX, sy: e.clientY, bx: b.x, by: b.y, moved: false };
    window.addEventListener('mousemove', onMove);
    window.addEventListener('mouseup', onUp);
  };
  // drag a corner handle to resize (RTL-aware: computed in visual-left coords)
  const onResizeStart = (id, corner, e) => {
    if (preview) return;
    e.stopPropagation();
    const b = page.blocks.find(x => x.id === id); if (!b) return;
    setSel(id); setEditing(null); pushHist();
    const pw = page.w || EW;
    drag.current = { type: 'resize', id, corner, sx: e.clientX, sy: e.clientY, by: b.y, bh: b.h, bw: b.w, vleft: pw - b.x - b.w, pw, moved: false };
    window.addEventListener('mousemove', onMove);
    window.addEventListener('mouseup', onUp);
  };
  const onMove = (e) => {
    const d = drag.current; if (!d) return;
    const dx = (e.clientX - d.sx) / scale, dy = (e.clientY - d.sy) / scale;
    if (Math.abs(dx) > 1 || Math.abs(dy) > 1) d.moved = true;
    if (d.type === 'resize') {
      const c = d.corner;
      const east = c === 'nw' || c === 'sw';   // logical-start handle = visual right edge
      const west = c === 'ne' || c === 'se';   // logical-end handle = visual left edge
      const north = c[0] === 'n', south = c[0] === 's';
      let vleft = d.vleft, top = d.by, w = d.bw, h = d.bh;
      if (west) { vleft = d.vleft + dx; w = d.bw - dx; }
      if (east) { w = d.bw + dx; }
      if (north) { top = d.by + dy; h = d.bh - dy; }
      if (south) { h = d.bh + dy; }
      w = Math.max(10, w); h = Math.max(10, h);
      const x = Math.round(d.pw - vleft - w);
      setPages(ps => ps.map((p, i) => i !== cur ? p : { ...p, blocks: p.blocks.map(b => b.id === d.id ? { ...b, x, y: Math.round(top), w: Math.round(w), h: Math.round(h), _dirty: true } : b) }));
      return;
    }
    setPages(ps => ps.map((p, i) => i !== cur ? p : { ...p, blocks: p.blocks.map(b => b.id === d.id ? { ...b, x: Math.round(d.bx - dx), y: Math.round(d.by + dy), _dirty: true } : b) }));
  };
  const onUp = () => {
    if (drag.current && drag.current.moved) markDirty();
    drag.current = null;
    window.removeEventListener('mousemove', onMove);
    window.removeEventListener('mouseup', onUp);
  };

  // page ops
  const addPage = () => { pushHist(); const np = { id: 'p' + Date.now(), name: 'עמוד חדש', kind: 'blank', bg: '#ffffff', w: page.w || EW, h: page.h || EH, blocks: [] }; setPages(ps => [...ps.slice(0, cur + 1), np, ...ps.slice(cur + 1)]); setCur(cur + 1); setSel(null); markDirty(); };
  const dupPage = (i) => { pushHist(); const np = clone(pages[i]); np.id = 'p' + Date.now(); np.name = pages[i].name + ' (עותק)'; np.blocks.forEach(b => b.id = b.id + '_' + Math.random().toString(36).slice(2, 6)); setPages(ps => [...ps.slice(0, i + 1), np, ...ps.slice(i + 1)]); markDirty(); };
  const delPage = (i) => { if (pages.length <= 1) return; pushHist(); setPages(ps => ps.filter((_, j) => j !== i)); setCur(c => Math.max(0, c - (i <= c ? 1 : 0))); setSel(null); markDirty(); };
  const movePage = (i, dir) => { const j = i + dir; if (j < 0 || j >= pages.length) return; pushHist(); const ps = [...pages]; [ps[i], ps[j]] = [ps[j], ps[i]]; setPages(ps); setCur(j); markDirty(); };
  const delBlock = () => {
    if (!sel) return; pushHist();
    setPages(ps => ps.map((p, i) => {
      if (i !== cur) return p;
      const victim = p.blocks.find(b => b.id === sel);
      // remember the original spot + its local bg colour so SmartMask blends the cover
      const deletedBoxes = victim && victim.originalBBox ? [...(p.deletedBoxes || []), { ...victim.originalBBox, color: victim.maskColor }] : (p.deletedBoxes || []);
      return { ...p, blocks: p.blocks.filter(b => b.id !== sel), deletedBoxes };
    }));
    setSel(null); markDirty();
  };
  const dupBlock = () => { if (!block) return; pushHist(); const nb = clone(block); nb.id = block.id + '_' + Math.random().toString(36).slice(2, 6); nb.x += 16; nb.y += 16; setPages(ps => ps.map((p, i) => i !== cur ? p : { ...p, blocks: [...p.blocks, nb] })); setSel(nb.id); markDirty(); };

  const zoom = (d) => setScale(s => Math.min(1.4, Math.max(0.25, +(s + d).toFixed(2))));

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%', background: 'transparent' }}>
      <EditorTop go={go} source={source} model={imported ? imported.model : 'Peugeot 3008'} sub={imported ? `מיובא מ-PDF · ${imported.source}` : 'Peugeot Passenger 2026'} saved={saved} scale={scale} zoom={zoom} setScale={setScale}
        undo={undo} canUndo={hist.length > 0} preview={preview} setPreview={setPreview}
        isImport={isImport} viewMode={viewMode} setViewMode={setViewMode} warnings={pageWarnings.length} onShowQA={() => setSel(null)} />

      <div style={{ flex: 1, display: 'flex', minHeight: 0 }}>
        {/* pages rail (start side = right in RTL) */}
        {!preview && (
          <div style={{ width: 116, background: 'rgba(255,255,255,.42)', WebkitBackdropFilter: 'var(--glass-blur)', backdropFilter: 'var(--glass-blur)', borderInlineEnd: '1px solid rgba(255,255,255,.55)', display: 'flex', flexDirection: 'column', flexShrink: 0 }}>
            <div style={{ padding: '12px 12px 8px', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
              <span style={{ fontSize: 11.5, fontWeight: 800, color: 'var(--ink-3)' }}>עמודים</span>
              <span style={{ fontSize: 11, fontWeight: 700, color: 'var(--ink-3)', fontFamily: 'var(--mono)' }}>{pages.length}</span>
            </div>
            <div className="scroll" style={{ padding: '4px 12px 12px', display: 'flex', flexDirection: 'column', gap: 10 }}>
              {pages.map((p, i) => (
                <PageThumb key={p.id} page={p} index={i} active={i === cur}
                  onClick={() => { setCur(i); setSel(null); setEditing(null); }}
                  onDup={() => dupPage(i)} onDel={() => delPage(i)} onUp={() => movePage(i, -1)} onDown={() => movePage(i, 1)}
                  canUp={i > 0} canDown={i < pages.length - 1} />
              ))}
              <button onClick={addPage} style={{ height: 116, borderRadius: 8, border: '1.5px dashed var(--line-2)', color: 'var(--ink-3)', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 5, fontWeight: 700, fontSize: 12 }} className="learn-card">
                <Icon name="plus" size={20} /> עמוד
              </button>
            </div>
          </div>
        )}

        {/* canvas */}
        <div className="scroll editor-canvas" style={{ flex: 1, display: 'flex', justifyContent: 'center', padding: preview ? '32px' : '40px', background: preview ? 'transparent' : 'rgba(255,255,255,.14)' }}
          onMouseDown={() => { if (canEdit) { setSel(null); setEditing(null); } }}>
          <div style={{ height: 'fit-content' }}>
            {!preview && (
              <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 14, color: 'var(--ink-2)' }}>
                <span style={{ fontWeight: 800, fontSize: 14 }}>{page.name}</span>
                <span dir="ltr" style={{ fontSize: 12, fontWeight: 700, color: 'var(--ink-3)', fontFamily: 'var(--mono)', display: 'inline-block' }}>{page.w || EW}×{page.h || EH} · {Math.round(scale * 100)}%</span>
              </div>
            )}
            <div style={{ width: (page.w || EW) * scale, height: (page.h || EH) * scale, transition: drag.current ? 'none' : 'width .15s, height .15s' }}>
              <div onMouseDown={e => e.stopPropagation()} style={{ width: page.w || EW, height: page.h || EH, transform: `scale(${scale})`, transformOrigin: 'top right', boxShadow: 'var(--sh-lg)', borderRadius: 2, overflow: 'hidden' }}>
                <CatalogPage page={page} editable={canEdit} selectedId={sel} onSelect={onSelect}
                  editingId={editing} onStartEdit={startEdit} onEditText={editBlockText} onResize={onResizeStart} hidden={hidden}
                  renderMode={isImport ? viewMode : undefined} />
              </div>
            </div>
          </div>
        </div>

        {/* right properties panel */}
        {!preview && (
          <div style={{ width: 290, background: 'rgba(255,255,255,.42)', WebkitBackdropFilter: 'var(--glass-blur)', backdropFilter: 'var(--glass-blur)', borderInlineStart: '1px solid rgba(255,255,255,.55)', display: 'flex', flexDirection: 'column', flexShrink: 0 }}>
            <div className="seg" style={{ margin: 12 }}>
              <button className={tab === 'design' ? 'on' : ''} onClick={() => setTab('design')} style={{ flex: 1 }}>עיצוב</button>
              <button className={tab === 'layers' ? 'on' : ''} onClick={() => setTab('layers')} style={{ flex: 1 }}>שכבות</button>
            </div>
            <div className="scroll" style={{ flex: 1, padding: '4px 14px 18px' }}>
              {tab === 'layers'
                ? <LayersPanel page={page} sel={sel} setSel={setSel} hidden={hidden} setHidden={setHidden} />
                : block
                  ? <PropsPanel block={block} update={updateBlock} onDup={dupBlock} onDel={delBlock} />
                  : <PageProps page={page} go={go} />}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

const VIEW_MODES = [['original', 'מקור'], ['editable', 'עריכה'], ['reconstructed', 'משוחזר'], ['compare', 'השוואה']];
const VIEW_MODE_HINT = {
  original: 'תצוגת ה-PDF המקורי בלבד — מקור האמת הויזואלי',
  editable: 'רקע PDF מקורי + שכבת בלוקים הניתנת לעריכה',
  reconstructed: 'בלוקים משוחזרים בלבד, ללא רקע מקורי',
  compare: 'מקור + שכבת עריכה שקופה עם מתאר — לאיתור פערים',
};

function EditorTop({ go, source, model, sub, saved, scale, zoom, setScale, undo, canUndo, preview, setPreview, isImport, viewMode, setViewMode, warnings, onShowQA }) {
  const imports = window.IMPORTS || [];
  return (
    <div style={{ height: 56, flexShrink: 0, background: 'rgba(255,255,255,.5)', WebkitBackdropFilter: 'var(--glass-blur)', backdropFilter: 'var(--glass-blur)', borderBottom: '1px solid rgba(255,255,255,.55)', boxShadow: 'var(--glass-hi)', display: 'flex', alignItems: 'center', gap: 14, padding: '0 16px', zIndex: 20 }}>
      <button className="icon-btn" onClick={() => go('dashboard')}><Icon name="arrowR" /></button>
      <div style={{ display: 'flex', alignItems: 'center', gap: 9 }}>
        <BrandBadge brand={window.DB.BRANDS.find(b => model && model.toLowerCase().includes(b.name.toLowerCase().split(' ')[0])) || window.DB.BRANDS[0]} size={28} />
        <div>
          <div style={{ fontWeight: 800, fontSize: 14.5, lineHeight: 1 }}>{model}</div>
          <div style={{ fontSize: 11, color: 'var(--ink-3)', marginTop: 2 }}>{sub}</div>
        </div>
      </div>
      {/* switch between any imported/scanned spec */}
      {imports.length > 0 && (
        <select className="seg" value={source && imports.some(i => i.key === source) ? source : ''}
          onChange={e => e.target.value && go('editor', { source: e.target.value })}
          title="בחר מפרט סרוק"
          style={{ height: 34, padding: '0 10px', borderRadius: 10, fontSize: 12.5, fontWeight: 700, color: 'var(--ink)', cursor: 'pointer', border: '1px solid var(--glass-brd)' }}>
          <option value="" disabled>בחר מפרט סרוק…</option>
          {imports.map(it => <option key={it.key} value={it.key}>{it.model}</option>)}
        </select>
      )}
      <span style={{ display: 'flex', alignItems: 'center', gap: 5, fontSize: 12, fontWeight: 700, color: saved === 'נשמר' ? 'var(--eco)' : 'var(--ink-3)', marginInlineStart: 6 }}>
        {saved === 'נשמר' ? <Icon name="checkCircle" size={14} /> : <span className="spinner" style={{ width: 11, height: 11, borderColor: 'var(--line-2)', borderTopColor: 'var(--ink-3)' }} />}{saved}
      </span>

      <div style={{ flex: 1 }} />

      {/* fidelity view-mode toggle — imported PDFs only */}
      {isImport && !preview && <>
        <div className="seg" title={VIEW_MODE_HINT[viewMode]} style={{ padding: 3 }}>
          {VIEW_MODES.map(([v, l]) => (
            <button key={v} className={viewMode === v ? 'on' : ''} onClick={() => setViewMode(v)} style={{ padding: '5px 10px', fontSize: 11.5 }}>{l}</button>
          ))}
        </div>
        {warnings > 0 && (
          <button onClick={onShowQA} className="chip chip-warn" title="בדיקת איכות ייבוא" style={{ cursor: 'pointer', height: 30 }}>
            <Icon name="alert" size={13} /> {warnings}
          </button>
        )}
        <div style={{ width: 1, height: 24, background: 'var(--line)', margin: '0 4px' }} />
      </>}

      {!preview && <>
        <button className="icon-btn" onClick={undo} style={{ opacity: canUndo ? 1 : .4 }}><Icon name="undo" /></button>
        <button className="icon-btn" style={{ opacity: .4 }}><Icon name="redo" /></button>
        <div style={{ width: 1, height: 24, background: 'var(--line)', margin: '0 4px' }} />
        <div style={{ display: 'flex', alignItems: 'center', gap: 2, background: 'var(--surface-3)', borderRadius: 9, padding: 3 }}>
          <button className="icon-btn" style={{ width: 30, height: 30 }} onClick={() => zoom(-0.1)}><Icon name="zoomOut" size={16} /></button>
          <button onClick={() => setScale(0.46)} style={{ fontSize: 12, fontWeight: 700, fontFamily: 'var(--mono)', width: 46, color: 'var(--ink-2)' }}>{Math.round(scale * 100)}%</button>
          <button className="icon-btn" style={{ width: 30, height: 30 }} onClick={() => zoom(0.1)}><Icon name="zoomIn" size={16} /></button>
        </div>
        <div style={{ width: 1, height: 24, background: 'var(--line)', margin: '0 4px' }} />
      </>}

      <button className="btn btn-ghost btn-sm" onClick={() => setPreview(p => !p)}>
        <Icon name={preview ? 'edit' : 'eye'} size={16} /> {preview ? 'עריכה' : 'תצוגה'}
      </button>
      <button className="btn btn-primary btn-sm" onClick={() => go('export')}><Icon name="download" size={16} /> ייצוא</button>
    </div>
  );
}

function PageThumb({ page, index, active, onClick, onDup, onDel, onUp, onDown, canUp, canDown }) {
  const [hover, setHover] = React.useState(false);
  return (
    <div onMouseEnter={() => setHover(true)} onMouseLeave={() => setHover(false)} style={{ position: 'relative' }}>
      <button onClick={onClick} style={{ display: 'block', width: '100%' }}>
        <div style={{ position: 'relative', width: '100%', aspectRatio: `${page.w || EW}/${page.h || EH}`, borderRadius: 7, overflow: 'hidden', background: page.bg,
          boxShadow: active ? '0 0 0 2px var(--accent), 0 4px 12px oklch(0.56 0.16 256 / .2)' : '0 0 0 1px var(--line), var(--sh-sm)', transition: '.14s' }}>
          <div style={{ width: page.w || EW, height: page.h || EH, transform: `scale(${92 / (page.w || EW)})`, transformOrigin: 'top right', pointerEvents: 'none' }}>
            <CatalogPage page={page} renderMode={page.kind === 'import' ? 'original' : undefined} />
          </div>
        </div>
      </button>
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginTop: 4, padding: '0 2px' }}>
        <span style={{ fontSize: 10.5, fontWeight: 700, color: active ? 'var(--accent)' : 'var(--ink-3)', fontFamily: 'var(--mono)' }}>{String(index + 1).padStart(2, '0')}</span>
        <span style={{ fontSize: 10.5, fontWeight: 600, color: 'var(--ink-3)', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', maxWidth: 58 }}>{page.name}</span>
      </div>
      {hover && (
        <div className="pop" style={{ position: 'absolute', top: 4, insetInlineEnd: 4, display: 'flex', gap: 3, background: 'rgba(255,255,255,.95)', borderRadius: 7, padding: 3, boxShadow: 'var(--sh)' }}>
          <MiniBtn icon="chevU" onClick={onUp} dim={!canUp} />
          <MiniBtn icon="chevD" onClick={onDown} dim={!canDown} />
          <MiniBtn icon="copy" onClick={onDup} />
          <MiniBtn icon="trash" onClick={onDel} danger />
        </div>
      )}
    </div>
  );
}

function MiniBtn({ icon, onClick, danger, dim }) {
  return <button onClick={(e) => { e.stopPropagation(); onClick(); }} style={{ width: 22, height: 22, borderRadius: 5, display: 'grid', placeItems: 'center', color: danger ? 'var(--danger)' : 'var(--ink-2)', opacity: dim ? .3 : 1 }} className="menu-item"><Icon name={icon} size={14} /></button>;
}

Object.assign(window, { ScreenEditor });


/* ===== screen_export.jsx ===== */

/* ============ PDF Export ============ */
function ScreenExport({ go }) {
  const pages = window.DB.CATALOG_PAGES;
  const [variant, setVariant] = React.useState('digital');
  const [fname, setFname] = React.useState('Peugeot_3008_Spec_2026');
  const [embed, setEmbed] = React.useState(true);
  const [marks, setMarks] = React.useState(false);
  const [phase, setPhase] = React.useState('idle'); // idle | rendering | done
  const [prog, setProg] = React.useState(0);

  React.useEffect(() => {
    if (phase === 'rendering') {
      if (prog < 100) { const t = setTimeout(() => setProg(p => Math.min(100, p + 7)), 90); return () => clearTimeout(t); }
      const t = setTimeout(() => setPhase('done'), 400); return () => clearTimeout(t);
    }
  }, [phase, prog]);

  const start = () => { setProg(0); setPhase('rendering'); };

  return (
    <div className="scroll">
      <div className="page-wrap" style={{ maxWidth: 1180 }}>
        <button onClick={() => go('editor')} style={{ display: 'flex', alignItems: 'center', gap: 6, color: 'var(--ink-3)', fontWeight: 700, fontSize: 13, marginBottom: 16 }}>
          <Icon name="chevR" size={16} /> חזרה לעורך
        </button>
        <div style={{ display: 'flex', alignItems: 'flex-end', justifyContent: 'space-between', marginBottom: 24 }}>
          <div>
            <h2 style={{ fontSize: 26, fontWeight: 800, letterSpacing: '-.5px', fontFamily: 'var(--display)' }}>ייצוא PDF</h2>
            <p style={{ color: 'var(--ink-2)', fontSize: 14.5, marginTop: 4 }}>Peugeot 3008 · 8 עמודים · Peugeot Passenger 2026</p>
          </div>
          <div style={{ display: 'flex', gap: 9 }}>
            <span className="chip chip-eco"><Icon name="globe" size={13} /> RTL מלא</span>
            <span className="chip chip-accent"><Icon name="font" size={13} /> פונטים מוטמעים</span>
          </div>
        </div>

        <div style={{ display: 'grid', gridTemplateColumns: '1fr 360px', gap: 24, alignItems: 'start' }}>
          {/* preview grid */}
          <div className="card" style={{ padding: 22 }}>
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 16 }}>
              <h3 style={{ fontSize: 15, fontWeight: 800 }}>תצוגה מקדימה · כל העמודים</h3>
              <span style={{ fontSize: 12.5, color: 'var(--ink-3)', fontWeight: 700, fontFamily: 'var(--mono)' }}>{pages.length} עמ׳</span>
            </div>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 16 }}>
              {pages.map((p, i) => {
                const tw = 344, tscale = tw / (p.w || window.DB.PAGE_W);
                return (
                <div key={p.id} className="pop" style={{ animationDelay: `${i * 0.03}s`, width: tw }}>
                  <div style={{ position: 'relative', width: tw, aspectRatio: `${p.w || window.DB.PAGE_W}/${p.h || window.DB.PAGE_H}`, borderRadius: 6, overflow: 'hidden', background: p.bg, boxShadow: '0 0 0 1px var(--line), var(--sh-sm)' }}>
                    <div style={{ width: p.w || window.DB.PAGE_W, height: p.h || window.DB.PAGE_H, transform: `scale(${tscale})`, transformOrigin: 'top right', pointerEvents: 'none' }}>
                      <CatalogPage page={p} />
                    </div>
                    {marks && <CropMarks />}
                  </div>
                  <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: 5, fontSize: 11, fontWeight: 700, color: 'var(--ink-3)' }}>
                    <span style={{ fontFamily: 'var(--mono)' }}>{String(i + 1).padStart(2, '0')}</span>
                    <span>{p.name}</span>
                  </div>
                </div>
                );
              })}
            </div>

            {/* version history */}
            <h3 style={{ fontSize: 15, fontWeight: 800, margin: '28px 0 14px' }}>היסטוריית גרסאות</h3>
            <div style={{ display: 'flex', flexDirection: 'column' }}>
              {window.DB.EXPORT_VERSIONS.map((v, i) => (
                <div key={v.v} style={{ display: 'flex', alignItems: 'center', gap: 13, padding: '12px 4px', borderBottom: i < 3 ? '1px solid var(--line)' : 'none' }}>
                  <div style={{ width: 36, height: 36, borderRadius: 9, background: v.current ? 'var(--accent-soft)' : 'var(--surface-3)', display: 'grid', placeItems: 'center', color: v.current ? 'var(--accent)' : 'var(--ink-3)', fontFamily: 'var(--mono)', fontWeight: 700, fontSize: 12.5 }}>{v.v}</div>
                  <div style={{ flex: 1 }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                      <span style={{ fontWeight: 700, fontSize: 13.5 }}>{v.note}</span>
                      {v.current && <span className="chip chip-accent" style={{ height: 20, fontSize: 10.5 }}>נוכחית</span>}
                    </div>
                    <div style={{ fontSize: 12, color: 'var(--ink-3)', marginTop: 2 }}>{v.by} · {v.when} · {v.size}</div>
                  </div>
                  <button className="icon-btn" style={{ width: 32, height: 32 }}><Icon name="download" size={16} /></button>
                  <button className="icon-btn" style={{ width: 32, height: 32 }}><Icon name="refresh" size={16} /></button>
                </div>
              ))}
            </div>
          </div>

          {/* export options */}
          <div style={{ display: 'flex', flexDirection: 'column', gap: 16, position: 'sticky', top: 0 }}>
            <div className="card" style={{ padding: 20 }}>
              <h3 style={{ fontSize: 15, fontWeight: 800, marginBottom: 16 }}>הגדרות ייצוא</h3>

              <Field label="גרסה">
                <div style={{ display: 'flex', flexDirection: 'column', gap: 9 }}>
                  <VariantOpt icon="globe" title="דיגיטלי" desc="RGB · אופטימלי לאינטרנט ולשליחה" on={variant === 'digital'} onClick={() => setVariant('digital')} />
                  <VariantOpt icon="print" title="דפוס" desc="CMYK · 300dpi · סימני חיתוך" on={variant === 'print'} onClick={() => { setVariant('print'); setMarks(true); }} />
                </div>
              </Field>

              <Field label="שם הקובץ">
                <div style={{ display: 'flex', alignItems: 'center', border: '1px solid var(--line-2)', borderRadius: 9, overflow: 'hidden', background: 'var(--surface)' }}>
                  <input value={fname} onChange={e => setFname(e.target.value)} dir="ltr" style={{ flex: 1, height: 38, padding: '0 11px', border: 'none', outline: 'none', fontSize: 13, fontFamily: 'var(--mono)', background: 'transparent', color: 'var(--ink)' }} />
                  <span style={{ padding: '0 11px', color: 'var(--ink-3)', fontSize: 13, fontFamily: 'var(--mono)', borderInlineStart: '1px solid var(--line)' }}>.pdf</span>
                </div>
              </Field>

              <div style={{ display: 'flex', flexDirection: 'column', gap: 2, marginBottom: 18 }}>
                <OptToggle label="הטמע פונטים" desc="עברית מלאה בכל מכשיר" on={embed} onClick={() => setEmbed(!embed)} />
                <OptToggle label="סימני חיתוך" desc="לדפוס מקצועי" on={marks} onClick={() => setMarks(!marks)} />
                <OptToggle label="איכות תמונה גבוהה" desc="ללא דחיסה" on={true} onClick={() => {}} />
              </div>

              {phase === 'idle' && (
                <button className="btn btn-primary btn-lg" style={{ width: '100%' }} onClick={start}>
                  <Icon name="download" /> ייצא PDF
                </button>
              )}
              {phase === 'rendering' && (
                <div>
                  <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 12.5, fontWeight: 700, marginBottom: 7 }}>
                    <span style={{ color: 'var(--accent)' }}>מרנדר עמודים…</span>
                    <span style={{ fontFamily: 'var(--mono)' }}>{prog}%</span>
                  </div>
                  <Progress value={prog} height={8} />
                </div>
              )}
              {phase === 'done' && (
                <div className="fade-up">
                  <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: 13, background: 'var(--eco-soft)', borderRadius: 11, marginBottom: 11 }}>
                    <Icon name="checkCircle" size={22} style={{ color: 'var(--eco)' }} />
                    <div>
                      <div style={{ fontWeight: 800, fontSize: 13.5, color: 'var(--eco)' }}>הקובץ מוכן!</div>
                      <div style={{ fontSize: 12, color: 'var(--ink-2)' }}>{fname}.pdf · 8.4MB · v5</div>
                    </div>
                  </div>
                  <div style={{ display: 'flex', gap: 9 }}>
                    <button className="btn btn-primary" style={{ flex: 1 }} onClick={() => setPhase('idle')}><Icon name="download" size={16} /> הורד</button>
                    <button className="btn btn-ghost"><Icon name="share" size={16} /></button>
                  </div>
                </div>
              )}
            </div>

            <div className="card" style={{ padding: 16, display: 'flex', gap: 11, fontSize: 12.5, color: 'var(--ink-2)', lineHeight: 1.5 }}>
              <Icon name="versions" size={18} style={{ color: 'var(--accent)', flexShrink: 0, marginTop: 1 }} />
              כל ייצוא נשמר כגרסה. תוכל לחזור לכל גרסה קודמת או להמשיך לערוך את המפרט בכל שלב.
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

function VariantOpt({ icon, title, desc, on, onClick }) {
  return (
    <button onClick={onClick} style={{ display: 'flex', alignItems: 'center', gap: 12, padding: 12, borderRadius: 11, textAlign: 'start',
      border: on ? '1.5px solid var(--accent)' : '1.5px solid var(--line-2)', background: on ? 'var(--accent-soft)' : 'var(--surface)', transition: '.14s' }}>
      <div style={{ width: 34, height: 34, borderRadius: 9, background: on ? 'var(--accent)' : 'var(--surface-3)', display: 'grid', placeItems: 'center', color: on ? '#fff' : 'var(--ink-3)', flexShrink: 0 }}>
        <Icon name={icon} size={17} />
      </div>
      <div style={{ flex: 1 }}>
        <div style={{ fontWeight: 800, fontSize: 13.5 }}>{title}</div>
        <div style={{ fontSize: 11.5, color: 'var(--ink-3)' }}>{desc}</div>
      </div>
      <CheckRing on={on} />
    </button>
  );
}

function OptToggle({ label, desc, on, onClick }) {
  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '10px 0', borderBottom: '1px solid var(--line)' }}>
      <div style={{ flex: 1 }}>
        <div style={{ fontWeight: 700, fontSize: 13.5 }}>{label}</div>
        <div style={{ fontSize: 11.5, color: 'var(--ink-3)' }}>{desc}</div>
      </div>
      <Toggle on={on} onClick={onClick} />
    </div>
  );
}

function CropMarks() {
  const m = { position: 'absolute', background: 'rgba(0,0,0,.5)' };
  return <>
    <div style={{ ...m, top: 0, insetInlineStart: '12%', width: 1, height: 6 }} />
    <div style={{ ...m, top: 0, insetInlineEnd: '12%', width: 1, height: 6 }} />
    <div style={{ ...m, bottom: 0, insetInlineStart: '12%', width: 1, height: 6 }} />
    <div style={{ ...m, bottom: 0, insetInlineEnd: '12%', width: 1, height: 6 }} />
  </>;
}

Object.assign(window, { ScreenExport });


